// Generated by npm run gen:packs. Edit public/data.js instead.
AF_ADD_PACK("ON", [{"id":"waterloo-ontario-renovates","name":"Ontario Renovates home repair and accessibility funding (Region of Waterloo)","level":"Region of Waterloo","category":"Housing","amount":"Maximum $25,000 for homeowner repairs and/or up to $25,000 for eligible accessibility modifications — limits may be subject to change","amountTiers":{"caption":"Maximum income by family size — All income maximums updated annually","headers":["Family size","Maximum income" ],"rows":[["One person","$41,210" ],["Two persons","$51,204" ],["Three persons","$63,072" ],["Four persons","$76,577" ],["Five persons","$86,853" ],["Six persons","$97,956" ],["Seven+ persons","$109,060" ] ]},"summary":"Limited funding for low- to moderate-income homeowners in Waterloo Region. It pays for eligible home repairs or accessibility changes for people with disabilities. It is a loan that is fully forgiven over 10 years. If accessibility changes are needed, up to $5,000 of the loan is a grant you do not repay.","note":"The fact sheet gives different dates. Households must apply before November 15, 2026 and have a signed agreement by December 15, 2026. It also says the deadline to submit an application is December 1, 2026. Check the current deadline with the Region. Eligible households are added to the Ontario Renovates List. It works on a first come, first served basis.","requires":["waterlooRegion","homeowner","waterlooRenovatesEligibility" ],"eligibility":{"mode":"all","items":["You own an existing home in Waterloo Region as your sole and principal residence; you cannot own other property, including a cottage, or have partial ownership of a property","The home has a maximum value of $600,000","The total gross income of all household members (including those with disabilities) is at or below the maximum for the family size, or the household receives Ontario Works or Ontario Disability Support Program financial support as its sole source of income","Property taxes and mortgage payments are up to date","Insurance coverage is in place for the full value of the home" ],"note":"All income maximums updated annually. If applicable, a household with disabled members can deduct the applicable Canada Revenue Agency tax credit for Persons with Disabilities for the previous year, from line 316 or 318."},"applyText":"See funding and application details","applyUrl":"https://www.regionofwaterloo.ca/programs-and-services/employment-and-financial-supports/financial-support-for-renters-and-homeowners/funding-for-home-repairs/","source":"https://www.regionofwaterloo.ca/programs-and-services/employment-and-financial-supports/financial-support-for-renters-and-homeowners/funding-for-home-repairs/","detail":{"about":"The Region of Waterloo delivers Ontario Renovates with funding from the federal and provincial governments through the Ontario Priorities Housing Initiative. There is a maximum of $25,000 per dwelling for homeowner repairs as a fully forgivable loan and/or up to $25,000 for eligible accessibility modifications for persons with disabilities; the maximum funding limits may be subject to change. Repairs and accessibility modifications up to and including $25,000 must be secured by a promissory note. If funding exceeds $25,000, a mortgage registered on title is required. The Ontario Renovates loan is forgivable over 10 years and does not need to be repaid if the homeowner remains the owner, lives in the home and does not default during that period. The maximum loan amount for accessibility modifications, if required, includes a grant portion up to $5,000 that does not require repayment.","aboutList":{"lead":"Limited Ontario Renovates funding helps qualified Waterloo Region homeowners with eligible repairs and accessibility modifications.","items":["Maximum $25,000 per dwelling for homeowner repairs as a fully forgivable loan and/or up to $25,000 for eligible accessibility modifications; maximum funding limits may be subject to change.","Up to and including $25,000 must be secured by a promissory note; if funding exceeds $25,000, a mortgage registered on title is required.","The forgivable-loan period is 10 years. No repayment is needed if the homeowner remains the owner, lives in the home and does not default during those 10 years.","Accessibility funding, if required, includes a grant portion up to $5,000 that does not require repayment.","Eligible repairs include building exteriors such as roofs, walls or foundations; doors and windows; plumbing; fire safety; electrical systems; heating systems; and mold remediation.","Eligible accessibility modifications include ramps; handrails; chair and bath lifts; height adjustments to counter tops; cues for doorbells or fire alarms; and bathroom modifications." ]},"steps":["Check the family-size income table or the alternative of Ontario Works or Ontario Disability Support Program financial support as the household's sole source of income; confirm the home-value, ownership, tax, mortgage and insurance requirements","Gather every required document — the application will not be processed unless all required documents are received","Submit the application by email, fax, mail or in person","If eligible, wait for the Region to contact you by phone to arrange a home inspection","The fact sheet says apply before November 15, 2026 and have a signed agreement by December 15, 2026. It also says: Deadline to submit application is December 1, 2026. Check the current deadline with the Region" ],"documents":["Photo identification","Income verification","A recent property assessment notice or property tax bill","Proof of home insurance","Proof that property taxes and mortgage payments are up to date" ],"tips":["The Region must receive all required documents, or it will not process your application.","The fact sheet says applications are accepted all year. 2026 funding is available after April 1, 2026, once the province confirms it.","The fact sheet gives different application dates. It says to apply before November 15, 2026. It also says the deadline to submit an application is December 1, 2026. You also need a signed agreement by December 15, 2026. Check the current deadline with the Region.","For emergencies such as heating problems or an urgent plumbing leak, call 519-575-4400.","Apply by email at OntarioRenovates@regionofwaterloo.ca or by fax at 519-575-4026. You can also apply by mail or in person at 20 Weber St. E., Kitchener; 150 Main St., Cambridge; or 99 Regina St. S., Waterloo." ],"phone":"519-575-4400"}},{"id":"waterloo-homemaking-support","name":"Homemaking Support Services Program (Region of Waterloo)","level":"Region of Waterloo","category":"Home support","amount":"Light housekeeping, meal planning and preparation, and laundry","summary":"The Region pays agencies to help eligible people live on their own. Help includes light housekeeping, meal planning and preparation, and laundry. The waitlist is about 2–3 years right now, except in special circumstances.","note":"When you reach the top of the waitlist, you must share all your financial and health information so they can confirm you are eligible. A crisis clean may be considered if there is a serious and immediate threat to a household's safety or housing, such as severe unsanitary conditions, infestation or hoarding.","requires":["waterlooRegion","waterlooHomemakingFinancial","waterlooHomemakingNeed" ],"eligibility":{"mode":"all","items":["You live in Waterloo Region","You meet the financial criteria through low income or social support","You have significant functional impairments that affect your ability to complete homemaking tasks","You need help at home due to illness, recovery from injury, aging or disability" ],"note":"Full financial and health information is required to confirm eligibility once you reach the top of the waitlist."},"applyText":"Apply through Caredove","applyUrl":"https://www.regionofwaterloo.ca/programs-and-services/seniors-and-long-term-care/community-programs-for-older-adults/homemaking-support/","source":"https://www.regionofwaterloo.ca/programs-and-services/seniors-and-long-term-care/community-programs-for-older-adults/homemaking-support/","detail":{"about":"The Region of Waterloo funds agencies to provide support to people who need assistance to live independently. Services are light housekeeping, meal planning and preparation, and laundry. The program is fully funded through the Ministry of Health and the Region of Waterloo. The waitlist is currently approximately 2–3 years, except under special circumstances.","aboutList":{"lead":"Homemaking support helps eligible Waterloo Region residents live independently at home.","items":["Light housekeeping.","Meal planning and preparation.","Laundry.","The waitlist is currently approximately 2–3 years, except under special circumstances.","Full financial and health information is required to confirm eligibility when you reach the top of the waitlist." ]},"steps":["Open the Homemaking Support Services Program application through Caredove","If you have trouble, choose “I'm signing up for myself, a family member or a friend” without requiring login credentials","Join the waitlist","When you reach the top, provide full financial and health information so the program can confirm eligibility" ],"documents":["Financial information when you reach the top of the waitlist","Health information when you reach the top of the waitlist" ],"tips":["The waitlist is currently approximately 2–3 years, except under special circumstances.","A crisis clean may be considered if there is a serious and immediate threat to household safety or housing. Examples are severe unsanitary conditions, infestation or hoarding. You are not automatically entitled to one.","For help, call the Homemaking Coordinator at 519-893-8494 extension 6342." ],"phone":"519-893-8494 ext. 6342"}},{"id":"waterloo-curbside-waste-support","name":"Curbside waste support programs (Region of Waterloo)","level":"Region of Waterloo","category":"Home support","amount":"Assisted cart collection, or 30 garbage bag tags a year at no charge for approved applicants","summary":"Two supports for Waterloo Region residents who make extra medical-related waste, or whose disability or physical limit makes it hard to put black and green carts at the curb. One is assisted cart set-out. The other is a medical exemption with 30 free garbage bag tags a year for approved applicants.","note":"Assisted Waste Collection moves your Region-issued black garbage cart and green organics cart from an agreed spot to the curb. Tagged bags are also collected. Staff do not empty indoor containers. They do not move carts from another location or collect outside the regular schedule. They do not go into homes or garages.","requires":["waterlooRegion","waterlooWasteSupportApproval" ],"eligibility":{"mode":"any","items":["For Assisted Waste Collection: you live with a disability or physical limitation, need help placing Region-issued black and green carts at the curb, and do not have someone available to help. It is available to eligible households that receive municipal curbside waste collection","For the Medical Exemption Program: medical needs create extra garbage, such as packaging, incontinence products or unrecyclable medical waste" ],"note":"The Region presents these as two support programs on one page. Approval depends on the requirements for the program you apply to."},"applyText":"See both waste support programs","applyUrl":"https://www.regionofwaterloo.ca/programs-and-services/garbage-and-organics/garbage/curbside-waste-support/","source":"https://www.regionofwaterloo.ca/programs-and-services/garbage-and-organics/garbage/curbside-waste-support/","detail":{"about":"The Region of Waterloo offers two support programs for residents who create extra medical-related waste and/or live with a disability or physical limitation that makes it difficult to place black and green carts at the curb for collection. Assisted Waste Collection helps eligible residents move Region-issued black garbage and green organics carts to the curb when no one is available to help. The Medical Exemption Program gives approved applicants 30 garbage bag tags per year at no charge for extra garbage created by medical needs.","aboutList":{"lead":"One page covers two different curbside waste supports.","items":["Assisted Waste Collection is for residents with a disability or physical limitation who need help placing Region-issued black garbage and green organics carts at the curb and do not have someone available to help. It is available to eligible households that receive municipal curbside waste collection.","It does not include emptying indoor containers into carts, moving carts from anywhere other than the agreed set-out location, or collecting waste outside the regular schedule.","Collection staff will not enter homes or garages.","The Medical Exemption Program is for medical needs that create extra garbage, such as packaging, incontinence products or unrecyclable medical waste.","Approved Medical Exemption applicants receive 30 garbage bag tags per year at no charge.","Extra garbage bags must be tagged and placed beside the garbage cart." ]},"steps":["Choose Assisted Waste Collection if you need help moving the Region-issued carts, or the Medical Exemption Program if medical needs create extra garbage","Review and apply through the Region's curbside waste support page","For the assisted service, agree on the cart set-out location","For the medical exemption, tag each extra garbage bag and place it beside the garbage cart" ],"documents":[ ],"tips":["The assisted service does not include indoor waste handling, a different cart location, extra collection days, or going into a home or garage.","If your Medical Exemption is approved, you get 30 garbage bag tags a year at no charge. Extra bags still need a tag and must be set beside the garbage cart." ]}},{"id":"grt-affordable-transit","name":"Affordable Transit Program (Grand River Transit)","level":"Region of Waterloo","category":"Transit","amount":"$47 monthly pass, $1.35 stored value per ride, or $6.75 for 5 MobilityPLUS tickets","amountTiers":{"caption":"Household net income at or below this limit","headers":["Household size","Net income limit" ],"rows":[["1 person","$31,875" ],["2 people","$45,078" ],["3 people","$55,208" ],["4 people","$63,749" ],["5 people","$71,724" ],["6 people","$78,077" ] ]},"summary":"The Affordable Transit Program gives discounted GRT fares to Waterloo Region residents on a low income. Eligibility depends on total household income.","note":"ATP costs $47 for a monthly pass instead of $104. Stored value is $1.35 per ride instead of the regular $3 stored-value fare or $4 cash fare. A strip of 5 ATP MobilityPLUS tickets costs $6.75 instead of $15.","requires":["waterlooRegion","lowIncome","atpApproval" ],"eligibility":{"mode":"all","items":["You are 18 or older","You live in the Region of Waterloo","You are not a full-time college or university student","Your household net income is at or below the limit" ],"note":"Income is household NET income: add line 23600 from each member's tax return. A household includes people you live with, are related to and financially support. Everyone counts even if they do not need a pass, and members over 18 must provide income information. If approved, all household members can buy the discounted fares, including all children 17 or younger."},"applyText":"Apply for the Affordable Transit Program","applyUrl":"https://www.grt.ca/fares-and-payment/affordable-transit-program/","source":"https://www.grt.ca/fares-and-payment/affordable-transit-program/","detail":{"about":"The Affordable Transit Program offers a discount on the price of GRT fare products for Waterloo Region residents living with low income. Eligibility is based on total household income and is managed by the Region of Waterloo Department of Community Services. The ATP monthly pass is $47 compared with the $104 regular monthly pass. ATP stored value is $1.35 per ride compared with $3 regular stored value and a $4 cash fare. ATP MobilityPLUS tickets are $6.75 for a strip of 5 compared with $15 regular.","aboutList":{"lead":"ATP discounts GRT fares for Waterloo Region households living with low income.","items":["$47 for an ATP monthly pass, compared with $104 for a regular monthly pass.","$1.35 ATP stored value per ride, compared with $3 regular stored value and a $4 cash fare.","$6.75 for a strip of 5 ATP MobilityPLUS tickets, compared with $15 regular.","Eligibility is managed by the Region of Waterloo Department of Community Services.","If approved, all household members can buy discounted fares, including all children 17 or younger." ]},"steps":["Add line 23600 from each household member's tax return and compare the total with the table","Gather the documents for your household's route","Apply online at https://webapps.regionofwaterloo.ca/ATP/ApplicationWizard/Step/Info when the online application is available. The GRT page says it is temporarily unavailable.","While it is unavailable you can still apply or get help from 8:30 to 4:30, Monday to Friday. Call Employment and Income Services at 519-883-2100 option 1, contact your Ontario Works caseworker directly, or visit a Community Services Welcome Space (150 Main St. Cambridge, 20 Weber St. Kitchener, 99 Regina St. S. Waterloo).","The GRT page says applications received during the interruption are processed within 7 days.","Ask for help at a Community Service Welcome Space if you need help completing the application" ],"documents":["If you receive Ontario Works or ODSP: your date of birth and your SAMS Member ID or SIN","If you do not receive Ontario Works or ODSP: proof of address — a valid driver's licence, Ontario photo ID card, government-issued mail, current utility bill, rent receipt or lease, or mortgage document","If you do not receive Ontario Works or ODSP: proof of income for each income-earning household member — a CRA Notice of Assessment showing line 23600, CRA Proof of income statement (Option C), or a letter from a Registered Social Worker","If you were a student in the last calendar year: proof of completion or graduation documents","If you are new to Canada in the current calendar year, you can submit one of: a PR or citizenship card, a refugee protection document, a verification of claim, a work permit, or confirmation of permanent residence" ],"tips":["Your household includes people you live with, are related to and support financially. Count everyone, even if they do not need a pass.","Household members over 18 must give income information.","If you are a registered MobilityPLUS customer on a low income, apply for ATP too. It lowers the cost of MobilityPLUS tickets." ]}},{"id":"grt-cnib-pass","name":"CNIB pass (Grand River Transit)","level":"Region of Waterloo","category":"Transit","amount":"Free unlimited travel on conventional GRT buses and ION light rail","summary":"An annual pass for CNIB customers. It gives unlimited use of regular GRT buses and ION light rail. CNIB customers ride free with a special CNIB EasyGO fare card.","note":"The source names conventional GRT buses and ION light rail. It does not say the pass includes MobilityPLUS.","requires":["waterlooRegion","cnibCustomer" ],"eligibility":{"mode":"all","items":["You are a CNIB customer" ],"note":"The CNIB pass is listed at no cost."},"applyText":"See the CNIB pass","applyUrl":"https://www.grt.ca/fares-and-payment/tickets-and-passes/passes/cnib-pass/","source":"https://www.grt.ca/fares-and-payment/tickets-and-passes/passes/cnib-pass/","detail":{"about":"The annual CNIB pass gives CNIB customers unlimited use of conventional GRT buses and ION light rail at no cost through a special CNIB EasyGO fare card. The card has Braille and a small notch in its side to make it easier to identify by touch.","aboutList":{"lead":"CNIB customers can ride conventional GRT buses and ION light rail free with a special EasyGO fare card.","items":["The pass is annual and costs nothing.","It provides unlimited use of conventional GRT buses and ION light rail.","The card has Braille and a small notch in the side to make it easier to identify by touch.","The source does not say MobilityPLUS is included." ]},"steps":["Contact GRT at 519-585-7597 to arrange to get your EasyGO fare card" ],"documents":[ ],"tips":["The tactile Braille and side notch help distinguish this card by touch." ],"phone":"519-585-7597"}},{"id":"grt-mobilityplus","name":"MobilityPLUS specialized transit (Grand River Transit)","level":"Region of Waterloo","category":"Transit","amount":"$15 for 5 tickets or $104 for a monthly pass; $6.75 for 5 tickets with ATP approval","summary":"MobilityPLUS runs in the urban areas of Waterloo Region. It is for eligible, registered customers whose disability affects their ability to travel on GRT buses or ION trains.","note":"This application is for residents of Cambridge, Kitchener and Waterloo. A separate specialized service exists for township residents.","requires":["waterlooUrban","waterlooMobilityPlusTransit" ],"needsPractitioner":true,"eligibility":{"mode":"any","items":["Unconditional — a disability prevents you from using conventional transit","Conditional — environmental or physical barriers limit your ability to consistently use conventional transit; you may be able to use conventional transit for all or part of a trip but may qualify for specialized transit under specific circumstances for some or all of your trip","Temporary — a temporary disability that prevents you from using conventional transit and requires specialized transit for a defined period of time" ],"note":"MobilityPLUS is only available to people who are eligible and registered."},"applyText":"Apply for MobilityPLUS","applyUrl":"https://www.grt.ca/mobilityplus/apply-for-mobilityplus/","source":"https://www.grt.ca/mobilityplus/apply-for-mobilityplus/","detail":{"about":"Grand River Transit MobilityPLUS operates within the urban areas of Waterloo Region. It provides specialized transit to eligible, registered customers who have a disability that impacts their ability to travel on GRT buses or ION trains. Eligibility may be unconditional, conditional or temporary. The application is for Cambridge, Kitchener and Waterloo residents; a separate specialized service exists for township residents.","aboutList":{"lead":"MobilityPLUS is specialized transit for eligible, registered Cambridge, Kitchener and Waterloo residents.","items":["Unconditional eligibility is for a person with a disability that prevents them from using conventional transit.","Conditional eligibility is for a person whose disability means environmental or physical barriers limit their ability to consistently use conventional transit. They may use conventional transit for all or part of a trip but qualify for specialized transit under specific circumstances for some or all of their trip.","Temporary eligibility is for a person with a temporary disability that prevents them from using conventional transit and requires specialized transit for a defined period of time.","MobilityPLUS tickets cost $15 for a strip of 5 and a monthly pass costs $104.","With ATP approval, a strip of 5 MobilityPLUS tickets costs $6.75." ]},"steps":["Complete Part A yourself or have your delegate complete it","Have a professional who can speak to your disability and ability to take conventional transit complete the Part B Health/Disability Professional form","Submit the two-part application" ],"documents":["Part A, completed by you or your delegate","Part B Health/Disability Professional form, completed by a health/disability professional who can speak to your disability and ability to take conventional transit" ],"tips":["Appropriate professionals could include (but are not limited to) a physician, nurse practitioner, psychiatrist, psychologist, optometrist, physiotherapist, occupational therapist, social worker, orientation and mobility specialist, kinesiologist, managers from pre-approved adult day programs or long-term care centres, and other professionals approved by the Region.","Township residents use a separate specialized service. This page does not give its rules.","If you live on a low income, apply for ATP too. It lowers a strip of 5 MobilityPLUS tickets from $15 to $6.75." ]}},{"id":"grt-taxi-coupons","name":"MobilityPLUS taxi coupons (Grand River Transit)","level":"Region of Waterloo","category":"Transit","amount":"$60 coupon book for $30, up to 30 books a year","summary":"MobilityPLUS customers can buy a taxi coupon book for $30. It holds $60 in $5, $2 and $1 coupons. The coupons have punched holes to show each value.","note":"Coupons are for the MobilityPLUS customer's personal use. They cannot be resold or transferred. Proven abuse results in privileges being revoked, and lost or stolen coupons are not reimbursed. Coupons do not expire and are not refundable.","requires":["waterlooUrban","mobilityplusRegistered" ],"eligibility":{"mode":"all","items":["You are a MobilityPLUS customer who lives and travels in Cambridge, Kitchener and Waterloo","You are not a MobilityPLUS North Dumfries or Kiwanis Transit customer (they are not eligible for taxi coupons)" ],"note":"Customers may purchase up to 30 coupon books between January 1 and December 31. Customers with seasonal eligibility may only buy during active registration periods."},"applyText":"See MobilityPLUS taxi coupons","applyUrl":"https://www.grt.ca/mobilityplus/taxi-coupons/","source":"https://www.grt.ca/mobilityplus/taxi-coupons/","detail":{"about":"A taxi coupon book contains $5, $2 and $1 coupons adding up to $60 and is sold to MobilityPLUS customers for $30. Holes are punched to identify each value. Coupons do not expire and are not refundable. Customers may purchase up to 30 books between January 1 and December 31; customers with seasonal eligibility may only buy during active registration periods.","aboutList":{"lead":"MobilityPLUS customers can buy $60 of taxi coupons for $30.","items":["Each book contains $5, $2 and $1 coupons, with holes punched to identify each value.","Coupons do not expire and are not refundable.","Up to 30 books may be purchased between January 1 and December 31.","Seasonal customers may buy only during active registration periods.","Coupons are personal, cannot be resold or transferred, and lost or stolen coupons are not reimbursed. Proven abuse results in privileges being revoked." ]},"steps":["Buy by phone at 519-585-7597 ext. 7347, Monday to Friday from 8:30 a.m. to 4 p.m.; a credit card is required","Or buy in person at a GRT customer service location","Or mail a cheque payable to Region of Waterloo to 250 Strasburg Rd., Kitchener, ON N2E 3M6, write your MobilityPLUS ID number on the front, and allow two weeks","When booking a taxi, tell the company you are using taxi coupons and say if you use a mobility device so it can arrange a suitable vehicle" ],"documents":["Your MobilityPLUS ID number for mail orders","A credit card for telephone orders, or a cheque payable to Region of Waterloo for mail orders" ],"tips":["Orders of three books or fewer go by Canada Post. Orders of four or more go by courier between 9 a.m. and 5 p.m. You must be home to accept the delivery.","The taxi companies named are Golden Triangle Taxi in Cambridge, and City Cabs, United Taxi and Waterloo Taxi in Kitchener and Waterloo.","Keep your coupons safe. Lost or stolen coupons are not paid back." ],"phone":"519-585-7597 ext. 7347"}},{"id":"grt-support-person","name":"Transit Support Person program (Grand River Transit)","level":"Region of Waterloo","category":"Transit","amount":"A support person travels free while providing assistance","summary":"For people who need regular or occasional help while travelling because of a disability. It covers GRT regular buses, MobilityPLUS buses and ION trains. The support person who helps you does not pay a fare.","note":"Your support person travels free. They can be a family member, friend, paid attendant or volunteer. They must be 13 years old or older and travel with you to help you use transit.","requires":["waterlooRegion","supportPersonApproval" ],"eligibility":{"mode":"all","items":["Due to a disability, you cannot travel independently on conventional or specialized transit service" ],"note":"The assistance may be regular or occasional."},"applyText":"Apply for the Transit Support Person program","applyUrl":"https://www.grt.ca/rider-information/transit-support-person-program/","source":"https://www.grt.ca/rider-information/transit-support-person-program/","detail":{"about":"The Transit Support Person program is for people who, because of disability, require regular or occasional assistance while travelling on GRT conventional buses, MobilityPLUS buses and/or ION trains. It is open to anyone who, due to a disability, cannot travel independently on conventional or specialized transit service. The support person providing assistance does not pay a fare.","aboutList":{"lead":"A support person travels free while assisting a customer who cannot travel independently because of disability.","items":["The program covers GRT conventional buses, MobilityPLUS buses and/or ION trains.","Assistance can be regular or occasional.","The support person can be a family member, friend, paid attendant or volunteer.","The support person must be 13 years of age or older and travel with you to assist you in using transit." ]},"steps":["Complete the online application","Or call GRT customer service to have a form mailed to you","Or pick up a form at any GRT customer service location","If you are not enrolled in PAL, the application should be completed by a registered health-care professional with one of the designations GRT lists (for example physician, nurse practitioner, nurse or occupational therapist, or others approved by the Region)" ],"documents":["A completed Transit Support Person application","If you are currently enrolled in the Personal Assistant for Leisure Activities program through the City of Kitchener, City of Waterloo or City of Cambridge: your PAL card number","If you are not in PAL: the part of the application that should be completed by a registered health-care professional with a designation GRT lists" ],"tips":["You may be enrolled in the Personal Assistant for Leisure Activities (PAL) program through the City of Kitchener, City of Waterloo or City of Cambridge. If so, your health care professional does not have to fill out the application. Give your PAL card number instead.","Your support person can be anyone 13 or older who travels with you to help. This includes a family member, friend, paid attendant or volunteer.","GRT does not pay back any fees a health-care professional charges." ]}},{"id":"york-region-homemakers","name":"Homemakers Services (York Region)","level":"York Region","category":"Daily living supports","amount":"Help with the cost of an in-home homemaker","summary":"York Region can help pay for an in-home homemaker. It is for people who are ill or disabled, either for a short time or for good. A homemaker helps with laundry, meals and light housekeeping.","note":"York Region runs this, not your city. It is the same program whether you live in Markham, Vaughan, Richmond Hill, Newmarket or Aurora.","requires":["yorkRegion","yorkHomemakersNeed" ],"eligibility":{"mode":"all","items":["You are temporarily or permanently ill or disabled","You meet the financial need requirements" ],"note":"York Region does not publish the financial need thresholds or the amount of help on this page — ask when you call."},"applyText":"Call York Region to apply","applyUrl":"https://www.york.ca/support/financial-assistance/homemakers-services","source":"https://www.york.ca/support/financial-assistance/homemakers-services","detail":{"about":"York Region can help cover the cost of an in-home homemaker for people who have a temporary or permanent illness or disability. Homemakers help with laundry, meals and light housekeeping. To be eligible you must be temporarily or permanently ill or disabled and meet financial need requirements.","aboutList":{"lead":"York Region helps pay for an in-home homemaker if illness or disability makes housework hard.","items":["A homemaker can help with laundry, meals and light housekeeping.","It covers temporary illness as well as permanent disability.","You need to meet financial need requirements.","It is a regional program, so it works the same across York Region's municipalities." ]},"steps":["Call York Region at 1-877-464-9675, or email ContactUs@york.ca","Ask about the financial need requirements, which are not published online" ],"documents":["Information about your illness or disability","Information about your finances, for the financial need assessment" ],"tips":["Short-term illness counts, not only lasting disability. It is worth asking about while you recover from surgery or a hospital stay.","The amount of help and the financial limits are not published. Contact York Region to find out where you stand." ],"phone":"1-877-464-9675"}},{"id":"york-region-recreation-subsidies","name":"Recreation subsidies (York Region)","level":"York Region","category":"Recreation","amount":"Subsidies for recreation programs, day camps and youth overnight camps","summary":"York Region funds subsidies for recreation and camps. Families who meet one of the Region's listed routes may be eligible. Children can join programs and camps run by their municipality. Overnight camp funding is for youth aged 12 to 17.","note":"York Region does not promise space in programs or camps. A subsidy is not a place. Searching your city's site will not find this. The Region funds it, and the city recreation departments run the programs.","requires":["yorkRegion","yorkRecreationAge","yorkRecreationFamilyRoute" ],"eligibility":{"mode":"all","items":["A family that meets at least one listed route may be eligible if it lives in York Region, such as receiving a rent subsidy, Ontario Works, ODSP or ACSD, or a child care fee subsidy with an annual income of $43,000 or less" ],"note":"Three subsidies are offered: Positive Leisure Activities for Youth (PLAY), summer day camp funding, and youth overnight camp funding. Overnight camp funding is for eligible youth aged 12 to 17. PLAY assists children ages four to 18 and single parents. Summer day camp is for children ages four to 12. Routes differ a little by subsidy. Day camp families on a child care fee subsidy contact their Children's Services Representative. Overnight camp also lists some housing communities."},"applyText":"See York Region recreation subsidies","applyUrl":"https://www.york.ca/support/financial-assistance/recreation-subsidies","source":"https://www.york.ca/support/financial-assistance/recreation-subsidies","detail":{"about":"York Region offers subsidies for recreation programs, day camps and youth overnight camps. For the recreation program and day camp subsidies, families who meet one of the Region's listed routes may be eligible. Children take part in programs offered by the municipal recreation departments. The youth overnight camp funding helps eligible youth aged 12 to 17 attend an approved overnight camp.","aboutList":{"lead":"York Region funds recreation and camp subsidies for children; families who meet one of the Region's listed routes may be eligible.","items":["Positive Leisure Activities for Youth, known as PLAY.","Summer day camp funding.","Youth overnight camp funding for eligible youth aged 12 to 17.","The programs themselves are run by your municipal recreation department.","A subsidy does not guarantee a space in a program or camp." ]},"steps":["Check which of the three subsidies fits — PLAY, summer day camp, or youth overnight camp","Apply through York Region","Register with your municipal recreation department for the program or camp itself" ],"documents":["Information about the benefit or subsidy your family receives (or, for the child care fee subsidy route, your income)" ],"tips":["Your city's website will not show this program. York Region funds it, and the city runs the programs.","The subsidy does not hold a spot for you, so register for the program early too.","It covers Aurora, East Gwillimbury, Georgina, King, Newmarket, Markham, Richmond Hill, Vaughan and Whitchurch-Stouffville." ]}},{"id":"ottawa-community-pass","name":"Community Pass — OC Transpo discount for ODSP recipients (Ottawa)","level":"Ottawa","category":"Transit","amount":"$43.25 a month, or $1.75 a ride","summary":"A discounted OC Transpo pass for Ottawa residents who get ODSP. It covers every route, including Para Transpo, with no top-up charge. The Access pass costs the same but does not include this.","note":"Community and Access passes both cost $43.25 a month, but Access holders pay a $2.75 top-up for every Para Transpo ride while the Community Pass includes Para Transpo with no top-up. If you receive ODSP and use Para Transpo, the Community Pass is the cheaper of the two. The rural fare is not included in either.","requires":["ottawa","ottawaOdspReceipt" ],"eligibility":{"mode":"all","items":["You are an Ottawa resident","You receive benefits under the Ontario Disability Support Program" ],"note":"To prove it you need your ODSP number — the 9-digit identification number on an ODSP document — together with a Presto card number or a Para Transpo ID number. Discounted fares cannot be used when paying cash; you need a Presto card."},"applyText":"See reduced fares","applyUrl":"https://www.octranspo.com/en/fares/reduced-fares/","source":"https://www.octranspo.com/en/fares/reduced-fares/","detail":{"about":"The Community Pass is OC Transpo's discounted fare for Ottawa residents who receive ODSP benefits. It costs $43.25 a month, or $1.75 per ride, and lets you ride on all routes including Para Transpo without paying a top-up. The rural fare is not included.","aboutList":{"lead":"The Community Pass is OC Transpo's ODSP discount.","items":["$43.25 for a monthly pass, or $1.75 per ride.","Valid on all routes, including Para Transpo, with no top-up charge.","The Para Transpo rural fare is not included.","You must use a Presto card — discounted fares are not available when paying cash.","For comparison, the regular adult fare is $4.10 a ride and $138.50 a month." ]},"steps":["Get your ODSP identification number from an ODSP document","Get a Presto card, or have your Para Transpo ID number to hand","Set the Community discount on your card at an OC Transpo Customer Service Centre, or by calling OC Transpo Customer Service — discounted monthly passes cannot be set anywhere else","Buy monthly passes up to 14 days before the month starts; a pass is valid only for the calendar month it is bought for" ],"documents":["Your 9-digit ODSP identification number from an ODSP document","A Presto card number, or a Para Transpo ID number" ],"tips":["If you use Para Transpo and get ODSP, choose the Community Pass over the Access pass. It is the same $43.25, but with no $2.75 Para Transpo top-up per ride.","You must set up discounted monthly passes at a Customer Service Centre or by phone, not at a store.","If verification is needed, a lawyer, notary, registered social worker, or a member of one of the regulated health colleges can act as a guarantor." ]}},{"id":"ottawa-access-pass","name":"Access pass — OC Transpo discount for Para Transpo customers (Ottawa)","level":"Ottawa","category":"Transit","amount":"$43.25 a month, plus a $2.75 top-up per Para Transpo ride","summary":"A discounted monthly OC Transpo pass for registered Para Transpo customers. It gives unlimited travel on the O-Train and all buses except Para Transpo. It takes about a third off the cash fare on Para Transpo trips.","note":"Access pass holders pay a $2.75 top-up for each Para Transpo ride. If you also get ODSP, compare it with the Community Pass. The Community Pass costs the same $43.25 and includes Para Transpo with no top-up.","requires":["ottawa","paraTranspoRegistered" ],"eligibility":{"mode":"all","items":["You are registered as a Para Transpo customer" ],"note":"You will be asked for your Para Transpo registration number. Discounted fares cannot be used when paying cash."},"applyText":"See reduced fares","applyUrl":"https://www.octranspo.com/en/fares/reduced-fares/","source":"https://www.octranspo.com/en/fares/reduced-fares/","detail":{"about":"The Access pass is a discounted monthly pass for people registered as Para Transpo customers. At $43.25 a month it gives unlimited rides on the O-Train and all buses that are not Para Transpo, and saves one third of the cash-fare price on each Para Transpo trip. Access pass holders pay a $2.75 top-up charge per ride to use Para Transpo.","aboutList":{"lead":"The Access pass is OC Transpo's discounted monthly pass for Para Transpo customers.","items":["$43.25 a month.","Unlimited travel on the O-Train and all non-Para Transpo buses.","Saves one third of the cash-fare price on each Para Transpo trip.","A $2.75 top-up is charged for each Para Transpo ride.","ParaPay and ParaPass cannot be used on OC Transpo buses or the O-Train." ]},"steps":["Register as a Para Transpo customer and note your registration number","Set the Access discount at an OC Transpo Customer Service Centre, or by calling OC Transpo Customer Service","Buy the monthly pass up to 14 days before the month begins" ],"documents":["Your Para Transpo registration number" ],"tips":["If you also get ODSP, check the Community Pass first. It costs the same and has no Para Transpo top-up.","Fare capping means that paying as you go with Presto never costs more than $12.25 in a day. In a month, it never costs more than the monthly pass price." ]}},{"id":"ottawa-equipass","name":"EquiPass — OC Transpo low-income discount (Ottawa)","level":"Ottawa","category":"Transit","amount":"$58.25 a month, or $1.75 a ride — about half an adult pass","summary":"A discounted OC Transpo pass for Ottawa residents whose family income is below the federal low income threshold, provided they do not already receive transportation benefits from Social Services.","note":"You cannot get EquiPass if you get transportation benefits from Social Services. If you get ODSP, look at the Community Pass instead. It costs less at $43.25 and includes Para Transpo.","requires":["ottawa","lowIncome" ],"eligibility":{"mode":"all","items":["Your family income is below the low income threshold set by the Government of Canada","You do not receive transportation benefits from Social Services" ],"note":"You apply with a completed EquiPass Application and Consent Form plus a Notice of Assessment from the Canada Revenue Agency for the most recent taxation year. If you do not have a Notice of Assessment, other documentation can be used instead."},"applyText":"See reduced fares","applyUrl":"https://www.octranspo.com/en/fares/reduced-fares/","source":"https://www.octranspo.com/en/fares/reduced-fares/","detail":{"about":"EquiPass is OC Transpo's fare discount for people on a low income. A monthly EquiPass costs $58.25, roughly half the $138.50 adult monthly pass, and the per-ride EquiPass fare is $1.75 against an adult fare of $4.10.","aboutList":{"lead":"EquiPass is OC Transpo's low-income fare discount.","items":["$58.25 for a monthly pass, about half the $138.50 adult pass.","$1.75 per ride, against $4.10 for an adult.","You must not be receiving transportation benefits from Social Services.","You must use a Presto card — discounted fares are not available when paying cash." ]},"steps":["Complete the EquiPass Application and Consent Form","Include your Canada Revenue Agency Notice of Assessment for the most recent taxation year, or other accepted documentation if you do not have one","Set the EquiPass discount at an OC Transpo Customer Service Centre, or by calling OC Transpo Customer Service","Buy the monthly pass up to 14 days before the month begins" ],"documents":["A completed EquiPass Application and Consent Form","A Canada Revenue Agency Notice of Assessment for the most recent taxation year, or other accepted documentation" ],"tips":["If you get ODSP, the Community Pass costs less at $43.25. It covers Para Transpo without a top-up.","A lawyer, notary, registered social worker or a member of a regulated health college can act as a guarantor on the application.","Paying per ride with Presto is capped at $12.25 a day. Over a month, it is capped at the monthly pass price." ]}},{"id":"ottawa-a-card","name":"a-card — free OC Transpo travel if you are blind or partially sighted (Ottawa)","level":"Ottawa","category":"Transit","amount":"Free travel on all routes except Para Transpo","summary":"The a-card lets people who are blind or partially sighted ride OC Transpo free on every route except Para Transpo. You qualify with a CNIB card or an Attorney-General of Ontario Guide Dog photo ID card.","note":"The a-card does not cover Para Transpo. If you use Para Transpo, look at the Access pass. If you also get ODSP, look at the Community Pass.","requires":["ottawa","visionDisability","aCardProof" ],"eligibility":{"mode":"any","items":["You hold a CNIB card","You hold an Attorney-General of Ontario Guide Dog photo ID card" ],"note":"Proof is a CNIB one-piece photo ID card, or the Attorney-General of Ontario Guide Dog photo ID card."},"applyText":"See reduced fares","applyUrl":"https://www.octranspo.com/en/fares/reduced-fares/","source":"https://www.octranspo.com/en/fares/reduced-fares/","detail":{"about":"The a-card gives free travel on all OC Transpo routes except Para Transpo to people who are blind or partially sighted. Eligibility is by holding a CNIB card or an Attorney-General of Ontario Guide Dog photo ID card.","aboutList":{"lead":"The a-card is free OC Transpo travel for people who are blind or partially sighted.","items":["Free on all routes except Para Transpo.","Qualify with a CNIB card or an Attorney-General of Ontario Guide Dog photo ID card.","Para Transpo trips are not covered by the a-card." ]},"steps":["Have your CNIB one-piece photo ID card, or your Attorney-General of Ontario Guide Dog photo ID card","Take it to an OC Transpo Customer Service Centre to get the a-card" ],"documents":["A CNIB one-piece photo ID card, or an Attorney-General of Ontario Guide Dog photo ID card" ],"tips":["The a-card does not cover Para Transpo. The Access pass does. If you get ODSP, the Community Pass does too." ]}},{"id":"london-ontario-renovates","name":"Ontario Renovates home repair and accessibility funding (London)","level":"London","category":"Home","amount":"A 10-year forgivable loan up to $25,000 — the first $5,000 is a grant for accessibility work","summary":"Federal and provincial funding, run by the City of London. It helps lower- and moderate-income homeowners make their home accessible or do essential repairs. They must be seniors aged 60 or older, or people with disabilities.","note":"Funding is limited. Applications close October 30, 2026 at 4:30 p.m. Apply early: it is first come, first served. You may be asked for more documents, such as a medical form, when they assess accessibility changes.","requires":["london","londonRenovatesEligibility" ],"eligibility":{"mode":"all","items":["A senior aged 60 or older, or a person with a disability","Annual gross household income at or below $95,000, from line 15000 of last year's Notice of Assessment","Total household liquid assets at or below $30,000, counting TFSAs, GICs, bonds, mutual funds and savings accounts","The home is your sole and principal residence in London or Middlesex County","Property tax assessment value at or below $320,000 — the assessed value, not the resale value","Mortgage payments and property taxes are up to date, and the home is insured for its full value" ],"note":"You are not eligible if you have received Ontario Renovates funding before, or if your household previously received funding from the Affordable Housing Program or the Off-Reserve Aboriginal Housing (Trust) Program. Community or social housing as defined under the Housing Services Act 2011 is excluded."},"applyText":"See how to apply","applyUrl":"https://london.ca/living-london/building-renovating/home-repair-accessibility-funding","source":"https://london.ca/living-london/building-renovating/home-repair-accessibility-funding","detail":{"about":"The Ontario Renovates Program is funded by the federal and provincial governments and delivered locally by the City of London. It gives financial assistance to low-to-moderate income seniors aged 60 or older and to people with disabilities, to increase accessibility or complete essential repairs in their home. Assistance is a one-time 10-year forgivable loan of up to $25,000. If you are approved for accessibility modifications, the first $5,000 of that is a one-time grant rather than a loan.","aboutList":{"lead":"Ontario Renovates helps London homeowners make their home accessible or carry out essential repairs.","items":["A one-time 10-year forgivable loan of up to $25,000.","For accessibility modifications, the first $5,000 is a grant, not a loan.","For seniors aged 60 or older and people with disabilities.","Accessibility work can include ramps, chair and bath lifts, handrails, grab bars, raised toilets, levered handles, accessible shower stalls, personal emergency response systems, height adjustable countertops and fire alarms.","Essential repairs can include heating systems, roofs, walls, floors, foundations, chimneys, doors and windows, electrical, plumbing, septic systems and vents." ]},"steps":["Check the income, liquid asset and property assessment limits before applying","Get three estimates for the proposed repairs or modifications, and take photographs of the work areas","Complete the 2026 Homeowner Application with supporting documentation","Include photo ID for every adult homeowner, your CRA Notice of Assessment, property tax assessment, and confirmation of mortgage and insurance","Apply as early as you can — funding is limited and processed first come, first served" ],"documents":["Completed and signed Ontario Renovates application forms with supporting documentation","Government-issued photo ID for all homeowners, such as a driver's licence, passport, citizenship document or Ontario photo card","Your CRA Notice of Assessment","Property tax assessment showing the assessed value and that payments are up to date","Confirmation of mortgage and of insurance coverage","A list of liquid assets for every household member aged 18 and over","Three estimates for the proposed repairs or modifications, plus pictures of the proposed work" ],"tips":["Do not start the work before you are approved. Work started or finished before approval is not eligible.","Cosmetic work is not covered. This includes driveway paving, painting and flooring. Landscaping, central air conditioning and solar panels are also not covered.","You may be asked for a medical form when they assess accessibility changes.","You can only get Ontario Renovates funding once.","Send questions to housingprograms@london.ca or call 519-661-2489 extension 7831." ],"phone":"519-661-2489 ext. 7831"}},{"id":"windsor-affordable-pass","name":"Affordable Pass Program (Windsor)","level":"Windsor","category":"Transit","amount":"Transit Windsor 30-day APP pass: $63 adult or $43.50 youth, before taxes","summary":"A fee subsidy for Windsor-Essex residents and households on a low income. For approved applicants, Transit Windsor lists a 30-day bus pass at $63 for adults or $43.50 for youth, before taxes.","note":"These are Transit Windsor's prices. Eligibility rules may differ between municipalities. If you live elsewhere in Windsor-Essex, contact your local municipal transit department. Funding is first come, first served. The local transit department decides all approvals, based on local demand and budgets.","requires":["windsor","lowIncome","p2pIncomeTest" ],"eligibility":{"mode":"all","items":["Residents who have lived within Windsor-Essex County for at least 30 days and who are able to demonstrate residency","A combined household income that is at, or below, the Market Basket Measure (MBM) thresholds" ],"note":"The programme page does not list the MBM thresholds; for further details it directs you to contact your local municipal transit department. International students, full-time post-secondary students and foreign workers are not eligible, although exceptions may apply within municipalities. Eligibility criteria may differ across municipalities."},"applyText":"See Affordable Pass details","applyUrl":"https://www.citywindsor.ca/residents/social-services/social-policy-and-pathway-to-potential/pathway-to-potential/p2p-programs/affordable-pass-program","source":"https://www.citywindsor.ca/residents/social-services/social-policy-and-pathway-to-potential/pathway-to-potential/p2p-programs/affordable-pass-program","detail":{"about":"Pathway to Potential is a poverty-reduction strategy for the Windsor-Essex region, jointly funded by the City of Windsor and County of Essex. Its Affordable Pass Program is a fee subsidy that provides affordable transportation for Windsor-Essex residents and households living on a low income by subsidizing eligible residents' bus-pass costs before taxes. Transit Windsor publishes 30-day APP prices of $63 for an adult and $43.50 for a youth. Eligibility criteria may differ across municipalities, so applicants must contact their local municipal transit department.","aboutList":{"lead":"The Affordable Pass Program lowers bus-pass costs for approved Windsor-Essex residents living on a low income.","items":["Transit Windsor's APP prices are $63 for an adult 30-day pass and $43.50 for a youth 30-day pass, before taxes.","Transit Windsor's regular Smart Pass prices are $124 for an adult aged 20 to 59, $85 for a youth aged 13 to 19, and $63 for a senior aged 60 and over.","Transit Windsor charges $3.95 for a single adult, senior or youth fare, including a 2-hour transfer.","The APP adult 30-day price and Transit Windsor's regular senior 30-day price are both $63, so the APP is worth less to a rider who is already 60 or over.","Other municipalities may have different eligibility criteria; contact your local municipal transit department if you live elsewhere in Windsor-Essex." ]},"steps":["Ask your local municipal transit department for the Market Basket Measure threshold for your family size — the programme page does not list it","Gather your proof of residency and your combined-household-income documents — you must also have lived within Windsor-Essex County for at least 30 days","Apply through your local municipal transit department; funding is available on a first-come, first-served basis","If Transit Windsor approves you, get the APP pass at the Windsor International Transit Terminal, 300 Chatham Street West — it is available only there, with proof of identification","Tell your municipality about any change to financial, residency or other circumstances within 30 days of the change taking effect" ],"documents":["Preferred proof of income: a Canada Child Benefit notice, a Notice of Assessment, or proof of Ontario Works or Ontario Disability Support Program benefits","One proof of residency: Ontario Driver's Licence, Ontario Health Card, Ontario Photo Card, current utility bill, property tax bill, lease or rental agreement, mortgage statement, or current bank statement","Proof of identification when getting a Transit Windsor APP pass at the Windsor International Transit Terminal","Additional documentation may be requested","If you cannot provide the required documents, or your circumstances recently changed in a way they do not reflect, a Letter of Endorsement may be used. It should be on professional letterhead, include the referring agency's contact information and the client's full name, outline the benefits the subsidy would provide, and indicate the barriers preventing application. Acceptance is at the discretion of the municipality" ],"tips":["Funding is first come, first served.","Each eligible person can get the discount for 12 months from the date of approval.","The local transit department decides all approvals. They depend on local demand and budgets.","Report any change to your finances, residency or other circumstances within 30 days of it taking effect. If you do not, the provider reserves the right to end your eligibility.","You cannot transfer your eligibility. You cannot sell, transfer, trade, give away or share passes.","You can only get the Transit Windsor APP pass at the Windsor International Transit Terminal, 300 Chatham Street West. Bring proof of identification." ]}},{"id":"windsor-recreation-assistance","name":"90% Recreation Discount (Windsor)","level":"Windsor","category":"Recreation","amount":"90% off eligible program registration fees, before taxes","summary":"The 90% Recreation Discount is part of the Pathway to Potential Recreation Assistance Program. It gives eligible Windsor-Essex residents 90% off eligible recreation program registration fees, before taxes.","note":"Eligibility may differ between municipalities. Apply or ask questions through your local municipal recreation department. Funding is first come, first served. The local recreation department decides all approvals, based on local demand and budgets.","requires":["windsorEssex","lowIncome","p2pIncomeTest" ],"eligibility":{"mode":"all","items":["Residents who have lived within Windsor-Essex County for at least 30 days and who are able to demonstrate residency","A combined household income that is at, or below, the Market Basket Measure (MBM) thresholds","A sustained sport, physical, cultural or artistic program — the City says these should run at least five weeks with at least one session per week — or a day camp or specialty camp, which must last at least five consecutive days for consideration" ],"note":"The programme page does not list the MBM thresholds; for further details it directs you to contact your local municipal recreation department. Competitive activities, travel teams, fitness centre orientations, personal training and private lessons are not eligible. Program eligibility may differ across municipalities."},"applyText":"See recreation assistance details","applyUrl":"https://www.citywindsor.ca/residents/social-services/social-policy-and-pathway-to-potential/pathway-to-potential/p2p-programs/recreation-assistance-program","source":"https://www.citywindsor.ca/residents/social-services/social-policy-and-pathway-to-potential/pathway-to-potential/p2p-programs/recreation-assistance-program","detail":{"about":"Pathway to Potential is a poverty-reduction strategy for the Windsor-Essex region, jointly funded by the City of Windsor and County of Essex. Its Recreation Assistance Program provides affordable recreational, cultural and artistic opportunities for Windsor-Essex residents living in low-income households. This record covers the 90% Recreation Discount, which subsidizes eligible residents for 90% off program registration fees before taxes. The Recreation Assistance Program also includes Third Party Partnerships, Targeted Initiatives and Universal Programs.","aboutList":{"lead":"The 90% Recreation Discount lowers eligible program registration fees for approved Windsor-Essex residents.","items":["90% off the program registration fee before taxes.","Funding covers program registration fees, but not equipment or material costs.","It extends to eligible programs and services delivered directly by municipal recreation departments and approved service organizations within Windsor-Essex County.","Payment is issued directly to the program provider, or you can request reimbursement if registration fees were paid in advance. A reimbursement request must be made within 30 days of payment.","Program eligibility may differ across municipalities; contact your local municipal recreation department." ]},"steps":["Ask your local municipal recreation department for the Market Basket Measure threshold for your family size — the programme page does not list it","Check that the activity meets the duration rules and is not one of the excluded activities","If a service organization runs the program, ask your local recreation department whether that organization is approved","Gather your proof of residency and your combined-household-income documents — you must also have lived within Windsor-Essex County for at least 30 days","Apply through your local municipal recreation department; funding is available on a first-come, first-served basis","Use approved funding within the calendar year, and tell your municipality about changes to your financial, residency or other circumstances within 30 days of the change taking effect" ],"documents":["Preferred proof of income: a Canada Child Benefit notice, a Notice of Assessment, or proof of Ontario Works or Ontario Disability Support Program benefits. The Canada Child Benefit notice is preferred for 90% Recreation Discount applicants","One proof of residency: Ontario Driver's Licence, Ontario Health Card, Ontario Photo Card, current utility bill, property tax bill, lease or rental agreement, mortgage statement, or current bank statement","Additional documentation may be requested","If you cannot provide the required documents, or your circumstances recently changed in a way they do not reflect, a Letter of Endorsement may be used. It should be on professional letterhead, include the referring agency's contact information and the client's full name, outline the benefits the subsidy would provide, and indicate the barriers preventing application. Acceptance is at the discretion of the municipality" ],"tips":["Funding goes to ongoing sport, physical, cultural or artistic programs. The City says they should run at least five weeks, with at least one session each week. Day camps and specialty camps must last at least five days in a row to be considered.","These are not eligible: competitive activities, travel teams, fitness centre orientations, personal training and private lessons.","Funding is available per eligible person per calendar year, and approved funding must be used within that calendar year. It is not transferable from one year to the next.","The local recreation department decides all approvals. They depend on local demand and budgets.","You cannot transfer your eligibility.","Before you register, ask your local recreation department if a service organization is approved." ]}},{"id":"hamilton-fare-assist","name":"HSR Fare Assist (Hamilton)","level":"Hamilton","category":"Transit","amount":"50% off single-ride PRESTO fares for a year","summary":"Half-price single-ride PRESTO fares on Hamilton transit. It is for households below the Low-Income Measure, including people who get ODSP or CPP Disability. It covers accessible DARTS trips and regular buses. It covers everyone eligible in the household.","note":"The discount does not apply to monthly or annual passes. It lasts one year from approval, and you re-apply each year. Fare Assist became permanent on January 1, 2026. It replaced two earlier programs. One was the Affordable Transit Pass for Ontario Works recipients. The other was the Temporary Transit Fare Special Program for people who use a personal mobility device such as a wheelchair, scooter or walker, and for CNIB cardholders.","requires":["hamilton","hamiltonFareRoute" ],"eligibility":{"mode":"all","items":["You live in Hamilton","You receive Ontario Works or ODSP, or your total household income is below the Statistics Canada Low-Income Measure for your family size" ],"note":"Eligibility is based on total household income regardless of where the income comes from — employment, Ontario Works, ODSP, the Canada Pension Plan disability benefit, Employment Insurance, or WSIB payments all count the same way. Recent refugees, newcomers to Canada, and people aged 18 or 19 who have not yet filed a tax return may also qualify. After-tax income limits by family size: $30,255 for 1 person, $42,787 for 2, $52,403 for 3, $60,510 for 4, $67,652 for 5, $74,109 for 6, $80,047 for 7, $85,574 for 8, $90,765 for 9 and $95,675 for 10."},"applyText":"Apply for Fare Assist","applyUrl":"https://www.hamilton.ca/home-neighbourhood/hsr/fares/hsr-fare-assist","source":"https://www.hamilton.ca/home-neighbourhood/hsr/fares/hsr-fare-assist","detail":{"about":"Fare Assist gives Hamilton residents living below the Statistics Canada Low-Income Measure a 50 per cent discount on single-ride PRESTO fares, for themselves and their family, for one year following approval. Eligibility is based on total household income regardless of income source. The discount applies to both conventional and accessible transit, so it covers trips taken on DARTS vehicles as well as HSR buses. The City estimates about 88,000 Hamiltonians will benefit.","aboutList":{"lead":"Fare Assist halves single-ride PRESTO fares for lower-income Hamilton households.","items":["50 per cent off current single-ride PRESTO fares, for one year after approval.","Applies to accessible transit as well as conventional buses, including trips on DARTS vehicles.","Covers every eligible member of the household, including a spouse and children aged 13 to 17. Children 12 and under already ride free with PRESTO.","After 11 paid PRESTO trips in the same week, from Monday 12:01 a.m. to Sunday 11:59 p.m., you are not charged again that week.","It does not apply to monthly or annual passes." ]},"steps":["Check your total household income against the Low-Income Measure for your family size","Apply through the City of Hamilton — if you receive Ontario Works or ODSP you give your Member ID; otherwise your total household income, from any source, must be below the Low-Income Measure for your family size","Once approved, the 50 per cent discount applies to single-ride PRESTO fares for one year","Load funds onto your PRESTO card as you need them","Re-apply each year to keep the discount" ],"documents":["If you receive Ontario Works or ODSP: your Member ID. Everyone else: a current Notice of Assessment for all family members","Your PRESTO card, which the discount is applied to","Identification showing your current address, such as a driver's license, health card or government-issued ID" ],"tips":["The discount covers DARTS accessible transit trips, not only regular HSR buses.","Where your income comes from does not matter. ODSP, CPP Disability, WSIB, Employment Insurance, Ontario Works and employment income are all treated the same.","Recent refugees, newcomers, and 18- or 19-year-olds who have not filed a tax return yet may still qualify.","The weekly cap means you ride free after 11 paid trips in the same Monday-to-Sunday week.","You may have been on the old Affordable Transit Pass or the mobility-device and CNIB fare program. Fare Assist replaced both on January 1, 2026." ]}},{"id":"brampton-activeassist","name":"ActiveAssist fee subsidy (Brampton)","level":"Brampton","category":"Recreation","amount":"$275 for each eligible family member, as one lump sum — a family of four receives $1,100","summary":"A City of Brampton fee subsidy that helps low-income families and individuals join recreation programs. It is added as a credit on your account. Once approved, you qualify for two years.","note":"An ActiveAssist amount that has expired is not renewed on its own. You have to re-apply. The City says it has received many more applications, so approvals are taking longer.","requires":["brampton","lowIncome" ],"eligibility":{"mode":"all","items":["You live in Brampton and can show proof of residency, such as a utility bill, lease agreement or driver's licence","You can provide proof of total family net income","You can provide proof of legal responsibility for every dependant listed on the application" ],"note":"The City describes the program as being for low-income families and individuals but does not publish an income threshold on this page. Confidentiality is always maintained."},"applyText":"Apply for ActiveAssist","applyUrl":"https://www.brampton.ca/EN/residents/Recreation/Active-Assist/","source":"https://www.brampton.ca/EN/residents/Recreation/Active-Assist/","detail":{"about":"ActiveAssist is a fee subsidy program offered by the City of Brampton, designed to help low-income families and individuals in Brampton participate in recreation programs. The assistance is given as a credit to your account. Once your application is approved, staff apply $275 for each eligible member of the family to the primary account holder as a single lump sum — so an approved family of four receives $1,100. Once approved, you qualify for the program for two years.","aboutList":{"lead":"ActiveAssist is Brampton's recreation fee subsidy for low-income families and individuals.","items":["$275 for each eligible family member, paid to the primary account holder as one lump sum.","An approved family of four receives $1,100.","Once approved, you qualify for two years.","Credits can be used toward most registered programs, drop-in programs and memberships, though some exclusions apply.","Confidentiality is always maintained." ]},"steps":["Gather proof of Brampton residency, proof of total family net income, and proof of legal responsibility for each dependant on the application","Apply online, attaching the required documentation","Or pick up and drop off an application form at any Brampton Recreation Centre","Or mail it to ActiveAssist Brampton, 2 Wellington St. W., Brampton, ON L6Y 4R2","A member of the team contacts you once the completed application is received" ],"documents":["Proof of residency, such as a utility bill, lease agreement or driver's licence","Proof of total family net income","Proof of legal responsibility for all dependants listed on the application" ],"tips":["The subsidy lasts two years, longer than most municipal recreation subsidies. It does not renew on its own, so re-apply when it expires.","Each eligible family member adds $275 to the lump sum, so list everyone who qualifies.","Some limits apply to what you can spend credits on. Ask at your recreation centre before you register.","The City says approvals are taking longer because of a rise in applications. Send questions to recreation@brampton.ca." ]}},{"id":"mississauga-activeassist","name":"ActiveAssist fee assistance (Mississauga)","level":"Mississauga","category":"Recreation","amount":"$275 a year for each eligible family member","summary":"Fee assistance that helps Mississauga residents in low-income households, and newcomers with refugee status, join City recreation and culture programs. Each eligible person on the application gets a credit for the year.","note":"The credit cannot be refunded and is good for one year. You re-apply with supporting documents every year. You cannot get ActiveAssist at the same time as another City fee assistance program, such as the Jerry Love Children's Fund.","requires":["mississauga","lowIncome" ],"eligibility":{"mode":"any","items":["An individual or family without dependants under 18, with net individual or combined family income below the Low Income Cut Off","A family with dependants under 18, with combined net family income below the Low Income Cut Off, shown with documentation such as Canada Child Benefits forms","A newcomer with refugee status, shown with a Confirmation of Permanent Residency, a Refugee Protection Claimant Document, or a document issued under a special IRCC program such as a CUAET visa, issued within the past year" ],"note":"You are not eligible if you are a child under 18 applying alone — a parent or legal guardian must apply with you — if you are a full-time college or university student with no dependants, or if you already receive another City fee assistance program. Low Income Cut Off amounts, updated May 1, 2026: $26,440 for 1 person, $32,179 for 2, $40,071 for 3, $49,991 for 4, $56,925 for 5, $63,131 for 6, and $69,337 for 7 or more."},"applyText":"Apply for ActiveAssist","applyUrl":"https://www.mississauga.ca/recreation-and-sports/sports-and-activities/assistance-programs/active-assist/","source":"https://www.mississauga.ca/recreation-and-sports/sports-and-activities/assistance-programs/active-assist/","detail":{"about":"ActiveAssist is the City of Mississauga's fee assistance program. It gives residents in low-income households, and newcomers with refugee status, access to recreation and culture programs. Each eligible family member listed on the application receives a non-refundable credit of $275 valid for one year, and applicants reapply with supporting documents annually.","aboutList":{"lead":"ActiveAssist helps Mississauga residents afford City recreation and culture programs.","items":["$275 for each eligible family member listed on the application.","The credit is non-refundable and valid for one year.","Open to low-income households and to newcomers with refugee status.","You reapply and provide supporting documents every year.","You cannot combine it with another City fee assistance program such as the Jerry Love Children's Fund." ]},"steps":["Check your net income against the Low Income Cut Off amount for your family size, or gather your refugee status document if that is your route","Complete the Fee Assistance Program Application at your local community centre, or apply online","Provide one or more original current supporting documents when you submit","The City processes applications within 15 business days","Once approved you receive an email with your account start date and registration information" ],"documents":["Documentation showing net individual or combined family income below the Low Income Cut Off","For a family with dependants under 18, documentation indicating those dependants, such as Canada Child Benefits forms","For a newcomer with refugee status, a Confirmation of Permanent Residency, Refugee Protection Claimant Document, or a document under a special IRCC program such as a CUAET visa, issued within the past year" ],"tips":["A child under 18 cannot apply alone. A parent or legal guardian fills out the application with them.","Full-time college and university students with no dependants are not eligible.","Bring original, current documents, not photocopies, when you submit the application.","Each eligible family member on the application gets their own $275, so list everyone who qualifies." ]}},{"id":"ottawa-hand-in-hand","name":"Ottawa Hand in Hand recreation fee support","level":"Ottawa","category":"Recreation","amount":"$185 a year per person toward City recreation and culture programs","summary":"Fee support for City of Ottawa recreation and culture programs, for residents who can show financial need. Receiving ODSP or Assistance for Children with Severe Disabilities counts as proof of financial need.","note":"A parent or guardian can transfer all or part of their fee support to a child in their household. You are encouraged to pay at least 25 per cent of the program cost yourself.","requires":["ottawa","lowIncome" ],"eligibility":{"mode":"all","items":["You live in the City of Ottawa","You are applying for yourself or for a dependant","You can show proof of identity, residency and financial need" ],"note":"Residents of all ages are eligible. Financial need can be shown by evidence of receiving Ontario Works, a Child Care Subsidy, Essential Health and Social Supports, the Ontario Disability Support Program, Assistance for Children with Severe Disabilities, or the Guaranteed Income Supplement; by a means test using the Low Income Cut-Off; or by a T451E Notice of Assessment or Child Tax Benefit form. Special circumstances may also be considered."},"applyText":"See how to apply for Hand in Hand","applyUrl":"https://ottawa.ca/en/recreation-and-parks/register-courses-and-camps/registration-terms-and-cancellations/financial-support-ottawa-hand-hand","source":"https://ottawa.ca/en/recreation-and-parks/register-courses-and-camps/registration-terms-and-cancellations/financial-support-ottawa-hand-hand","detail":{"about":"Ottawa Hand in Hand is the City of Ottawa's recreation and culture fee support program. Each qualifying individual, or member of a family, is eligible for an annual amount of fee support of $185 per person, which can be used toward programs and activities offered by the Recreation, Cultural and Facility Services Department. Only City of Ottawa residents may apply, on their own behalf or for a dependant.","aboutList":{"lead":"Ottawa Hand in Hand helps with the cost of City recreation and culture programs.","items":["$185 a year for each qualifying person, including each member of a family.","Covers programs and activities run by the City's Recreation, Cultural and Facility Services Department.","Residents of all ages are eligible.","A parent or guardian can transfer all or part of their entitlement to a child in their household.","Applicants are encouraged to pay at least 25 per cent of the program cost themselves." ]},"steps":["Gather proof of identity, residency and financial need — be ready to provide copies of formal documentation","If you receive Ontario Works, ask your case worker to complete the application for you","Otherwise complete the application form, or pick one up at most staffed recreation facilities or at a Client Service Centre","Bring the completed form to your local recreation or cultural facility, where a supervisor reviews it for approval","Apply as early as you can, before the program registration period opens" ],"documents":["Proof of identity and of Ottawa residency","Proof of financial need — for example evidence of receiving ODSP, Assistance for Children with Severe Disabilities, Essential Health and Social Supports or the Guaranteed Income Supplement, a Low Income Cut-Off means test, a T451E Notice of Assessment, or a Child Tax Benefit form" ],"tips":["You can only get approved in person at a recreation or cultural facility, not online.","Apply as early as you can before registration opens. Popular programs fill up.","If you get ODSP or Assistance for Children with Severe Disabilities, that is accepted as proof of financial need.","Unlike some other cities' subsidies, a parent or guardian can move their fee support to a child in the household." ]}},{"id":"toronto-fair-pass","name":"Fair Pass Transit Discount (Toronto)","level":"Toronto","category":"Transit","amount":"36% off adult single fares — $2.10 instead of $3.30, capped at $98.70 a month","summary":"A discount on TTC and Wheel-Trans fares for lower-income Toronto residents. It is loaded onto your PRESTO card for 12 months. If you get ODSP or Ontario Works, you already meet the income test.","note":"The TTC sets the amounts, and they may change. They are based on paying with PRESTO. From August 1, 2026, the program reviews eligibility every year. Active Ontario Works, ODSP and Child Care Fee Subsidy clients are reviewed for renewal. If the City cannot verify your eligibility from its records, it will contact you with next steps.","requires":["toronto","torontoFairPassAge","lowIncome" ],"eligibility":{"mode":"all","items":["Between 20 and 64 years of age","Live in the City of Toronto","Have a PRESTO card number","Total after-tax family income below 75% of the Low-Income Measure After-Tax threshold. The City counts income for family members aged 20 to 64 (one line of its page says over 18)." ],"note":"Residents already receiving Ontario Works, Emergency Assistance or ODSP meet the financial eligibility criteria. If you are 13 to 19 or 65 and over, ask the TTC about youth, student and seniors fares instead. The City's income table says income is only calculated for family members aged 20 to 64, while another line says family members over 18; ask the City who is counted."},"applyText":"Apply for Fair Pass","applyUrl":"https://www.toronto.ca/community-people/employment-social-support/support-for-people-in-financial-need/assistance-through-ontario-works/transit-discount/","source":"https://www.toronto.ca/community-people/employment-social-support/support-for-people-in-financial-need/assistance-through-ontario-works/transit-discount/","detail":{"about":"The Fair Pass Transit Discount Program gives a full year of savings on TTC and Wheel-Trans trips by taking 36 per cent off adult single fares, applied directly to your PRESTO card. The discount is programmed onto the card for 12 months and reduces each adult single ride by $1.20. Once you have paid for 47 trips in the same month you pay no more for TTC travel that month, so the most you pay is $98.70.","aboutList":{"lead":"Fair Pass takes 36 per cent off adult single TTC fares for lower-income Toronto residents.","items":["Covers both TTC and Wheel-Trans trips.","A regular adult single fare of $3.30 costs you $2.10, saving $1.20 a ride.","After 47 paid trips in the same month you pay nothing more that month — a cap of $98.70.","The discount is loaded onto your PRESTO card and lasts 12 months.","Receiving Ontario Works, Emergency Assistance or ODSP means you already meet the income test." ]},"steps":["Get a PRESTO card and note its card number","Gather proof of income for yourself and every family member 18 or older, or your Ontario Works, ODSP or Child Care Fee Subsidy program identification number instead","Apply online, or call 416-338-8888 for a paper application, help by phone, or language interpretation","Once approved, the discount is programmed onto your PRESTO card for 12 months" ],"documents":["Your PRESTO card number","An email address and your Toronto address","Information for yourself and each family member living with you","Your Ontario Works member ID, ODSP member ID, or Child Care Fee Subsidy household or client file number — or proof of income documents instead" ],"tips":["If you get Ontario Works, Emergency Assistance or ODSP, you meet the financial criteria. You do not need income documents if you get Ontario Works, ODSP or Child Care Fee Subsidy. Emergency Assistance is not on that list, so you may need to give proof of income.","The discount covers Wheel-Trans as well as regular TTC service.","The Human Services Integration Office helps people who get social assistance apply by phone. It also offers language interpretation and paper applications if you ask.","Some clients must reapply. If you actively get Ontario Works, ODSP or Child Care Fee Subsidy, you may not need to. If you do, the City contacts you 45 days before your discount expires. From August 1, 2026, eligibility is reviewed every year." ],"phone":"416-338-8888"}},{"id":"toronto-welcome-policy","name":"Welcome Policy recreation fee subsidy (Toronto)","level":"Toronto","category":"Recreation","amount":"$683.04 a year for a child or youth up to 24; $314.60 a year at 25 and over","summary":"A yearly credit toward City of Toronto recreation programs for lower-income residents. It covers registered programs, instructional swim and sport, camps, after-school care, memberships and multi-use passes.","note":"The credit is valid for 12 months from the date your application is approved, does not carry over into the next year, and is not transferable between family members. You must re-apply and submit documents each year.","requires":["toronto","lowIncome" ],"eligibility":{"mode":"all","items":["The main applicant is 18 years of age or older","You live in the city of Toronto","Total after-tax family income, counting every family member over 18, is below the Low-Income Measure After-Tax threshold" ],"note":"The Welcome Policy income thresholds were last updated on February 25, 2026 using Statistics Canada's LIM-AT 2023 data: $30,255 for 1 person, $42,787 for 2, $52,403 for 3, $60,510 for 4, $67,652 for 5, $74,109 for 6 and $80,047 for 7. Statistics Canada updates LIM-AT annually."},"applyText":"Apply for the Welcome Policy","applyUrl":"https://www.toronto.ca/community-people/employment-social-support/child-family-support/welcome-policy-recreation-fee-subsidy/","source":"https://www.toronto.ca/community-people/employment-social-support/child-family-support/welcome-policy-recreation-fee-subsidy/","detail":{"about":"The Welcome Policy gives lower-income Toronto residents a financial credit toward City-operated recreation programs. The credit is valid for 12 months from the date an application is approved and is set per person per year: $683.04 for a child or youth up to age 24, and $314.60 for an adult or older adult aged 25 and over. Credits are not transferable between family members and do not carry over, so you re-apply each year. It is administered by the Human Services Integration Office.","aboutList":{"lead":"The Welcome Policy is a yearly credit toward City of Toronto recreation programs for lower-income residents.","items":["$683.04 a year for a child or youth up to age 24.","$314.60 a year for an adult or older adult aged 25 and over.","Can be used for registered recreation programs, instructional swim and sport programs, camps and after-school care.","Also covers memberships and multi-use passes, including Junior Golf and Ski memberships.","Valid 12 months from approval, not transferable between family members, and does not carry over." ]},"steps":["Check your total after-tax family income against the Welcome Policy threshold for your family size","Gather proof of income for each family member 18 or older, or your Ontario Works member ID, ODSP member ID or Child Care Fee Subsidy household or client file number instead","Apply through the City of Toronto, or call 416-338-8888 for help","Once approved, use the credit toward recreation registrations for the next 12 months","Re-apply and submit documents again the following year" ],"documents":["Proof of income for each family member 18 or older — or your program identification number if you receive Ontario Works, ODSP or Child Care Fee Subsidy","Documents for each family member included in the application" ],"tips":["Amounts are per person per year. You cannot move them between family members.","The credit does not carry over, so use it within the 12 months.","To add new family members or children in your temporary care to an existing file, call the Human Services Integration Office at 416-338-8888.","Only income for family members aged 18 and over counts toward the threshold." ],"phone":"416-338-8888"}},{"id":"trillium-drug-program","name":"Trillium Drug Program","level":"Ontario","category":"Health","amount":"Covers eligible drugs above a deductible that for most people is about 4% of after-tax household income, then up to $2 for each drug filled or refilled","summary":"Helps Ontario households with high prescription-drug costs compared with their income. For most people the deductible is about 4% of after-tax household income, paid in four quarterly amounts; once you have paid a quarter's amount, you pay up to $2 for each drug filled or refilled until the end of that quarter.","note":"For the deductible, your household income is the net income you reported to the Canada Revenue Agency for the previous tax year. This is the amount on line 23600 of your Notice of Assessment. Subtract any amount you withdrew from a Canadian Registered Disability Savings Plan, shown on line 12500 of your tax return. Only money your household actually pays out of pocket counts toward the deductible. Amounts covered by private insurance, a drug company or a discount card do not count.","requires":["on","tdpDeductible" ],"eligibility":{"mode":"all","items":["You live in Ontario and have a valid Ontario health card number","You do not already qualify for the Ontario Drug Benefit program (for example, you are not enrolled in a program such as Ontario Works)","You do not have an insurance plan that pays for 100% of your drugs","You spend about 4% or more of your after-tax household income on prescription-drug costs" ],"note":"You apply as a household. You can apply for yourself if you live alone or only with people the page does not list. Otherwise you have to include your spouse (the page lists married and some other partner cases) and another person you live with if one of you is a parent, grandparent or legal guardian of the other and one of you is dependent on the other for support."},"applyText":"Apply to the Trillium Drug Program","applyUrl":"https://www.ontario.ca/page/get-help-high-prescription-drug-costs","source":"https://www.ontario.ca/page/get-help-high-prescription-drug-costs","detail":{"about":"The Trillium Drug Program helps Ontarians pay for high prescription-drug costs relative to their household income. It covers the cost of more than 5,900 medications available through the Ontario Drug Benefit program, plus almost 1,500 additional drug products that meet specific criteria through the Exceptional Access Program. You pay a deductible first — for most people about 4% of household income after taxes, split into four quarterly amounts — and once a quarter's amount is paid you pay up to $2 for each drug filled or refilled until the end of that quarter.","aboutList":{"lead":"The Trillium Drug Program helps Ontario households with high prescription-drug costs relative to their income.","items":["Covers more than 5,900 medications available through the Ontario Drug Benefit program, plus almost 1,500 more through the Exceptional Access Program.","For most people the deductible is about 4% of household income after taxes.","Once a quarter's deductible is paid, you pay up to $2 for each drug filled or refilled until the end of that quarter.","The deductible is divided into four equal quarterly amounts across the four quarters of the program year.","The program year runs from August 1 to July 31." ]},"steps":["Check that you live in Ontario, have a valid Ontario health card, do not already qualify for the Ontario Drug Benefit, and do not have insurance covering 100% of your drugs","Complete the Trillium Drug Program application on the Ontario Drug Benefit Program Online Applications and Forms website, applying as a household","If you do not have a computer, request a paper form and guide by phone or email","Once enrolled you receive a confirmation letter telling you your deductible for the year and listing everyone covered","Tell your pharmacist, doctor or nurse practitioner that you have applied, so they can prescribe drugs covered by the Ontario Drug Benefit Program" ],"documents":["Your Ontario health card number","Your household's income information from the previous tax year, including line 23600 of your Notice of Assessment","Receipts for eligible drugs your household has paid for out of pocket" ],"tips":["Apply by September 30 to be repaid for eligible drugs you got in the previous program year. The program year runs August 1 to July 31.","Your enrolment renews automatically every year if you file your income taxes on time. You get a yearly confirmation letter.","Money you withdraw from a Canadian Registered Disability Savings Plan is subtracted from the income used to work out your deductible.","Only what your household pays out of pocket counts toward the deductible. Amounts paid by private insurance, a drug company or a drug discount card do not count.","You do not pay the whole deductible at once. It is split into four equal quarterly amounts across the program year.","Each new quarter starts with that quarter's deductible. An unpaid amount carries over to the next quarter, but not into the next year." ],"phone":"1-800-575-5386"}},{"id":"passport-program","needsPractitioner":true,"name":"Passport program (adults with a developmental disability)","level":"Ontario","category":"Community supports","amount":"$5,665 a year, up to $45,604 based on assessed need","summary":"Funding for adults 18 or older with a developmental disability. It helps them take part in their community and live as independently as possible, and it gives their caregivers a break. It is a reimbursement program: you send in receipts and are repaid up to your annual allocation.","note":"Every Passport recipient gets at least $5,665 a year. You may get more, up to $45,604. This depends on your assessed level of need and on funding becoming available. Passport agencies keep a waiting list for the additional amounts.","requires":["on","age18plus","passportDevelopmental","passportDso" ],"eligibility":{"mode":"all","items":["Has a developmental disability","Is 18 years old or older","Is a resident of Ontario","Either needs support to participate in the community while still in school, or has left school and is living with family or independently in a supportive living arrangement" ],"note":"A developmental disability should be determined by a psychologist or psychological associate registered with the College of Psychologists of Ontario, or the equivalent body in another province."},"applyText":"Apply through Developmental Services Ontario","applyUrl":"https://www.ontario.ca/page/passport-program-adults-developmental-disability","source":"https://www.ontario.ca/page/passport-program-adults-developmental-disability","detail":{"about":"Passport helps adults 18 or older with a developmental disability take part in their communities and live as independently as possible, and it helps their caregivers take a break from caregiving. It is a reimbursement program: you submit invoices and receipts for admissible expenses and are reimbursed up to your annual funding allocation. Passport is funded by the Ontario government and administered by local Passport agencies. All recipients receive a minimum of $5,665 a year, and it is possible to receive more, up to a maximum of $45,604, based on assessed need.","aboutList":{"lead":"Passport funds services and supports for adults with a developmental disability.","items":["Pays for taking part in community classes or recreational programs, developing work, volunteer and daily life skills, hiring a support worker, person-directed planning, and temporary respite for caregivers.","It is a reimbursement program — you submit invoices and receipts and are repaid up to your annual allocation.","Every recipient receives a minimum of $5,665 a year.","More is possible, up to a maximum of $45,604, based on your assessed level of need and as funding becomes available.","Funded by the Ontario government and administered by local Passport agencies." ]},"steps":["Contact your local Developmental Services Ontario (DSO) office, which manages applications for provincially funded adult developmental services","DSO confirms whether you are eligible for government-funded adult developmental services","Once confirmed, DSO connects you with your local Passport agency for $5,665 a year in funding","To seek more than $5,665, complete an application package so DSO can fully assess your needs; your information then goes to your local Passport agency","Submit invoices and receipts for admissible expenses to be reimbursed up to your allocation" ],"documents":["The developmental disability should be determined by a psychologist or psychological associate registered with the College of Psychologists of Ontario, or the equivalent body in another province","Invoices and receipts for admissible expenses, to claim reimbursement" ],"tips":["Tell DSO if anything in your application changes. They can then reassess you and re-prioritize you using the most up-to-date information.","If you are approved for more than $5,665 and accept between April and September, you get a full 12-month amount in the first year. If you accept between October and March, you get a 6-month amount in the first year and a full year after that. Either way, you get at least $5,665 in your first year.","Passport agencies keep the list of people waiting for additional funding above $5,665.","Claims for a service or product you received on or before March 31, 2026 must be submitted by March 31, 2027.","From March 31, 2027, you have 12 months after the end of each fiscal year (which ends March 31) to submit claims. This is for anything bought on or after April 1, 2026." ]}},{"id":"hvmp","name":"Home and Vehicle Modification Program","level":"Ontario","category":"Home","amount":"Funding for approved home or vehicle modifications (no published maximum)","summary":"Pays for changes to your home or vehicle. It is for children, adults and seniors with a disability that limits mobility. The changes help them keep living safely at home, take part in their community, and avoid losing a job. The Ontario page sends applicants to March of Dimes for eligibility and application details.","note":"You must first use any other public or private funding you can get before you can be considered eligible. If your household income is over $38,000, you may have to pay part of the cost of the modification.","requires":["on","hvmpMobility","hvmpIncome","hvmpCoordinator" ],"eligibility":{"mode":"all","items":["A permanent Ontario resident","A household income that does not exceed the established threshold","A disability that impedes mobility and results in substantial restriction in activities of daily living, such as personal care or accessing medical care or community services" ],"note":"Applicants must also meet other criteria set out in the Home and Vehicle Modification Program Guidelines. The program's service coordinator decides whether an applicant is eligible and approves expenditures."},"applyText":"See how to apply","applyUrl":"https://www.ontario.ca/page/home-and-vehicle-modification-program","source":"https://www.ontario.ca/page/home-and-vehicle-modification-program","detail":{"about":"The Home and Vehicle Modification Program provides home or vehicle modifications so that children, adults and seniors with disabilities that restrict mobility can continue living safely in their homes, participate in their communities, and avoid job loss. It is intended to serve individuals and families most in need of assistance. Applicants must first access any other sources of available public or private funding before being considered eligible, and applicants with a household income over $38,000 may be required to contribute toward the cost.","aboutList":{"lead":"The Home and Vehicle Modification Program pays for changes to a home or vehicle for a person whose disability restricts their mobility.","items":["Home changes can include ramps, platform and stairway lifts, elevating devices, widening doors, rearranging a bathroom or kitchen for safe use, environmental controls, and a wet room using universal design.","Vehicle, garage and carport changes can include hand or foot controls, lifts, specialized seating, remote garage-door openers, raising a roof or lowering a floor, and barrier-free garage modifications.","Funding can also cover an assessment completed after you apply, professional fees for planning the work, equipment and warranties, installation and labour, and training on how to use the equipment.","You must first access any other available public or private funding.","With a household income over $38,000 you may be required to contribute toward the cost." ]},"steps":["Check that you are a permanent Ontario resident with a disability that restricts mobility and substantially limits your daily activities","Access any other sources of public or private funding available to you first","Visit the March of Dimes website to learn about eligibility and how to apply","The program's service coordinator determines eligibility and approves expenditures, and may assess your home or vehicle if more information is needed" ],"documents":["Information about your household income","Information about your disability and how it restricts your mobility and daily activities" ],"tips":["You must use other available public or private funding before the program will consider you eligible.","A household income over $38,000 may mean you pay part of the cost of the modification.","If a specialized adapted appliance is only sold as a whole item, the program pays the difference between its cost and the market value of a similar non-specialized appliance.","Equipment such as hand controls and lifts should be fully convertible where possible, so it can move to another vehicle later.","Special Services at Home will not repay structural home or vehicle changes that this program covers." ]}},{"id":"ssah","needsPractitioner":true,"name":"Special Services at Home (SSAH)","level":"Ontario","category":"Children","amount":"Funding for respite and support services (no published amount)","summary":"Funding for families caring for a child under 18 with a physical and/or developmental disability. It buys respite for caregivers, support for the child's day-to-day activities, and activities that help the child grow and develop.","note":"SSAH is a discretionary program. Funding depends on available resources, so meeting the eligibility rules does not guarantee an amount. It is meant to add to other services a child gets. It will not repay anything already funded by another government program. This includes devices paid for by the Assistive Devices Program and home or vehicle changes covered by the Home and Vehicle Modification Program.","requires":["on","child","ssahDocumentation" ],"eligibility":{"mode":"all","items":["The child needs extra support, beyond what is expected for their age, because of a physical and/or developmental disability, so they can take part in daily activities at home and in the community","The child is under 18 years old","The child is a resident of Ontario and legally entitled to live in Canada","The child lives at home with their main caregiver, or lives separately without support from other government-funded out-of-home (residential) services" ],"note":"\"Legally entitled to live in Canada\" includes a citizen, a permanent resident, a holder of a Canadian Temporary Resident Permit, or a refugee entitled to live in Canada. Visitors are not eligible. Only one person with decision-making responsibility for the child can apply."},"applyText":"See how to apply for SSAH","applyUrl":"https://www.ontario.ca/page/special-services-home","source":"https://www.ontario.ca/page/special-services-home","detail":{"about":"Special Services at Home (SSAH) helps families taking care of a child with a developmental and/or physical disability. It provides funding to buy services and supports that help parents care for their child, or that help the child join activities at home and in the community. SSAH is meant to complement other services the child is already receiving, including clinical services. It is a discretionary program, so funding is provided according to available resources.","aboutList":{"lead":"Special Services at Home (SSAH) funds services and supports for a family caring for a child with a physical and/or developmental disability.","items":["Support for the child to take part in day-to-day activities — help with daily routines and self-care, sensory items, tutoring, and support that keeps the child safe.","Support for the child's growth and development — building a skill, joining family and social activities, fitness, and planning for the future.","Respite for main caregivers — a respite worker, camp fees, overnight or daytime respite, before and after school care, care on PA days and during March and summer breaks, household help while you care for your child, and training to support your child.","It complements other services rather than replacing them, and it is discretionary — funding depends on available resources." ]},"steps":["Gather documentation of your child's functional limitations from a regulated health professional","Gather proof of the child's Ontario residency, proof they are legally entitled to live in Canada, and a document confirming their date of birth","Complete the SSAH application form — only one person with decision-making responsibility for the child applies","Send the application to your local Ministry regional office","If approved, choose whether to manage the funding yourself or have an agency manage it for you, then submit your expenses to be reimbursed" ],"documents":["Documentation from a regulated health professional of the child's functional limitations resulting from a physical or developmental disability","Proof of the child's residency in Ontario, such as a school registration document, your valid Ontario driver's licence, or a utility bill","Proof the child is legally entitled to live in Canada, such as a Canadian passport or birth certificate, Certificate of Indian Status, Permanent Resident card, immigration documents, or a Canadian Temporary Resident Permit","Proof of the child's age, such as a birth or baptismal certificate, Ontario health card, or passport" ],"tips":["A regulated health professional records the functional limitations. This can be a physician, psychologist, psychological associate, nurse practitioner, registered nurse or registered practical nurse, ophthalmologist, optometrist, audiologist, physiotherapist, occupational therapist, psychotherapist, social worker, speech language pathologist, or behaviour analyst.","You can hire someone yourself, work through an agency, or pay a family member over 18 who is not the main caregiver, parent, step-parent or spouse. A parent, step-parent or spouse can never be paid.","SSAH will not repay things another government program already funds. This includes devices paid for by the Assistive Devices Program and home or vehicle changes covered by the Home and Vehicle Modification Program.","It also does not cover basic living expenses, transportation, dental care, private school tuition, or hands-on therapy and assessments. These include ABA, speech-language therapy, occupational or physical therapy, and psychotherapy.","You have one year from your funding end date to submit expenses. Funding received between April 1, 2025 and March 31, 2026 must be claimed by March 31, 2027.","For an infant without a definitive diagnosis, the regulated health professional gives a written statement. It describes the probability or presence of delay, and the risk of further delay that will cause ongoing functional limitations. Eligibility is then decided again at about age 6." ]}},{"id":"acsd","name":"Assistance for Children with Severe Disabilities (ACSD)","level":"Ontario","category":"Children","amount":"$25 to $678 a month","summary":"A monthly payment to help families with the extra costs of caring for a child under 18 who has a severe disability. This includes travel to appointments, special shoes and clothes, and parental relief such as respite. Children with severe disabilities may also get drug, dental and vision coverage.","note":"The federal Canada Disability Benefit is exempt as income for ACSD. It will not affect your eligibility or your payment. The maximum monthly payment is tied to inflation and adjusted each July. It rose 1.9% on July 1, 2026.","requires":["on","child","acsdSeverity","acsdIncome" ],"eligibility":{"mode":"all","items":["You are the parent or guardian of a child under 18 (17 and under) who has a severe disability","The child lives at home","Your total household income is $77,640 or less" ],"note":"Your eligibility and the amount you receive also depend on the size of your family, the severity of your child's disability, and the extraordinary costs related to that disability."},"applyText":"Apply for ACSD","applyUrl":"https://www.ontario.ca/page/assistance-children-severe-disabilities-program","source":"https://www.ontario.ca/page/assistance-children-severe-disabilities-program","detail":{"about":"The Assistance for Children with Severe Disabilities program (ACSD) gives parents and guardians financial support toward the extra costs of caring for a child with a severe disability. Eligible families receive between $25 and $678 a month, depending on household income, family size, and the child's disability-related costs. Alongside the monthly payment, children with severe disabilities may also receive coverage for an assistive-device assessment and/or the consumer contribution for a device under the Assistive Devices Program, prescription drugs, dental care, hearing aids and vision care.","aboutList":{"lead":"ACSD gives parents and guardians money toward the extra costs of caring for a child with a severe disability.","items":["Between $25 and $678 a month, depending on your household income, the size of your family, and your child's disability-related costs.","Helps with travel to doctors' appointments, hospitals and other appointments related to the child's disability, special shoes and clothes, and parental relief such as respite.","Children with severe disabilities may also receive coverage for an assessment for an assistive device and/or the consumer contribution for a device provided under the Assistive Devices Program, plus batteries and repairs for mobility devices.","They may also receive coverage for prescription drugs through OHIP+, dental care through Healthy Smiles Ontario, and hearing aids and vision care including eyeglasses.","The maximum is tied to inflation and adjusted each July; it rose 1.9% on July 1, 2026." ]},"steps":["Check that your child is under 18, lives at home, has a severe disability, and that your household income is $77,640 or less","Apply online — you can save, edit and submit later, but you have 90 days before the application expires","Or download the paper application and send it to your local ministry regional office","Submit one application per child; duplicate applications for the same child delay processing","A special agreements officer reviews your application and may contact you for more information, then you receive a decision letter" ],"documents":["Information about your total household income","Information about your child's disability and the extraordinary costs related to it" ],"tips":["Children with severe disabilities may also get coverage for batteries and repairs for mobility devices. The Assistive Devices Program itself does not fund these.","If you have more than one child with a severe disability, submit a separate application for each.","You have 90 days to finish and submit an online application. After that, you have to start a new one.","If you need help with the application, a community agency, health care professional, social worker, family member or friend can help you complete it.","If you disagree with the decision, you can ask for an internal review within 30 days of getting the decision letter." ]}},{"id":"on-adp","needsPractitioner":true,"name":"Assistive Devices Program (Ontario)","level":"Ontario","category":"Equipment","amount":"Up to 75% of the approved amount (may be the full amount if you receive ODSP, Ontario Works or ACSD)","summary":"Helps pay for customized equipment and specialized supplies for a long-term physical disability. This includes wheelchairs and other mobility aids, hearing aids, visual aids, prosthetics, respiratory and ventilator equipment, and diabetic and ostomy supplies. Your income is not considered.","note":"ADP does not pay for repairs. Care and maintenance are yours to pay for. It also does not cover many common items. These include bath and shower aids, grab-bars, stair or chair lifts, hospital beds, incontinence supplies, home renovations such as ramps, and batteries, even for equipment first bought through ADP.","requires":["on","equipmentNeed","adpClinical" ],"eligibility":{"mode":"all","items":["Generally, an Ontario resident with a valid Ontario health card","Generally, a physical disability requiring the equipment or supplies for 6 months or longer","Generally, meet the clinical criteria specific to the device you are applying for","Not already qualifying for, or receiving, financial support for the same equipment or supplies from the Workplace Safety and Insurance Board. Group \"A\" veterans are also excluded if they already qualify for, or receive, support from Veterans Affairs Canada" ],"note":"Your income is not considered."},"applyText":"See how to apply by device type","applyUrl":"https://www.ontario.ca/page/assistive-devices-program","source":"https://www.ontario.ca/page/assistive-devices-program","detail":{"about":"The Assistive Devices Program (ADP) helps people with long-term physical disabilities pay for customized equipment, like wheelchairs and hearing aids, and for specialized supplies such as those used with ostomies. Income is not considered. How much you get depends on the device: ADP may pay 75% of an approved fixed price, up to 75% of an approved maximum contribution, or a set grant amount paid directly to you. If you receive Ontario Works, ODSP or Assistance for Children with Severe Disabilities, ADP may cover the full approved price, the full maximum contribution, or the full grant amount.","aboutList":{"lead":"The Assistive Devices Program (ADP) helps pay for customized equipment and specialized supplies for a long-term physical disability.","items":["Covers things like mobility aids, hearing aids, visual aids, prosthetics, respiratory and ventilator equipment, home oxygen therapy, communication aids, and diabetic, ostomy and enteral-feeding supplies.","Your income is not considered.","ADP may pay 75% of an approved fixed price, up to 75% of an approved maximum contribution, or a grant paid directly to you.","If you receive Ontario Works, ODSP or Assistance for Children with Severe Disabilities, ADP may cover the full amount.","Repairs are not covered, and many common items are excluded." ]},"steps":["Check that the equipment or supplies you need are a category ADP funds","See a registered authorizer for your device type, who assesses you and confirms you meet the clinical criteria for it","Buy the device from an ADP-registered vendor, who usually bills ADP for its share directly. For a grant, ADP pays you directly and you can buy from any business you choose","Pay your share of the cost, plus any optional accessories or services you choose" ],"documents":["A valid Ontario health card","The application form for your device type, completed by a registered authorizer" ],"tips":["Income is not part of the test. ADP does not look at what you earn.","Generally, you must need the equipment for 6 months or longer.","ADP does not cover repairs, and you are responsible for care and maintenance.","If you cannot afford your share, Easter Seals Ontario, The War Amps and Lions Clubs may be able to help.","Replacement may be funded if your condition changes, or if the equipment is out of warranty and cannot be repaired at a reasonable cost." ],"phone":"1-800-268-6021 (TTY 1-800-387-5559)"}},{"id":"ontario-autism-program","name":"Ontario Autism Program","level":"Ontario","category":"Children","amount":"Needs-based services and supports","summary":"Services and supports for children and youth on the autism spectrum in Ontario, until they turn 18. They include foundational family services, caregiver-mediated early years programs, core clinical services, an entry to school program, and urgent response services.","note":"Register once through AccessOAP, the program's independent intake organization. You do not need to register again if you already registered with the Ontario Autism Program. You also do not need to if you already sent a registration form and supporting documents to the Ministry of Children, Community and Social Services.","requires":["on","child","autismSelected","oapDiagnosis" ],"eligibility":{"mode":"all","items":["The child is under 18 years old","The child currently lives in Ontario","The child has a written diagnosis of autism from a qualified professional" ],"note":"The written diagnosis must include the child's full name and date of birth, the date of the assessment, a statement that the child meets the diagnostic criteria for autism spectrum disorder, and the qualified professional's name and credentials."},"applyText":"Register through AccessOAP","applyUrl":"https://www.ontario.ca/page/ontario-autism-program","source":"https://www.ontario.ca/page/ontario-autism-program","detail":{"about":"The Ontario Autism Program (OAP) supports families of children and youth on the autism spectrum. Children receive services and supports until they turn 18. Registration goes through AccessOAP, the program's independent intake organization, whose care coordinators answer questions, explain your service options, and help you find needs-based services in your community.","aboutList":{"lead":"The Ontario Autism Program (OAP) supports families of children and youth on the autism spectrum.","items":["Children receive services and supports until they turn 18.","Foundational family services are available to everyone registered.","Caregiver-mediated early years programs are for children between 12 and 48 months.","There are also core clinical services, an entry to school program for children starting kindergarten or Grade 1, and urgent response services.","AccessOAP care coordinators help you understand your options and find services near you." ]},"steps":["Get a written autism diagnosis from a qualified professional, with the details the program requires","Create an AccessOAP account","Register your child through AccessOAP and provide all the supporting documentation they ask for","Work with an AccessOAP care coordinator to understand your service options" ],"documents":["The written autism diagnosis, showing the child's full name and date of birth, the assessment date, a statement that the child meets the diagnostic criteria for autism spectrum disorder, and the professional's name and credentials" ],"tips":["Register once. You do not need to register again if you already registered with the OAP or already sent a registration form and supporting documents to the ministry.","If you registered before April 2021, ask about interim one-time funding and childhood budgets.","Behaviour plans are no longer part of the program. Other services have replaced them.","Your child may also qualify for Special Services at Home or the Assistance for Children with Severe Disabilities program." ],"phone":"1-833-425-2445"}},{"id":"odsp","needsPractitioner":true,"name":"Ontario Disability Support Program (ODSP) — income support","level":"Ontario","category":"Income support","amount":"Up to $1,436/mo for a single person","summary":"Monthly income support for Ontario adults with a disability who are in financial need. It gives money toward basic needs and shelter, plus health benefits including prescription drugs and vision care. The amount depends on your family size, shelter costs and other income.","note":"If you already get CPP-D or QPP-D, you are in a \"prescribed class\", so you skip the disability determination process. You must still apply and meet all the other rules. The federal Canada Disability Benefit is exempt as income and does not reduce your ODSP payment.","requires":["on","age18plus","odspMedical","odspFinancial" ],"eligibility":{"mode":"all","items":["At least 18 years old (you can start applying up to six months before your 18th birthday)","An Ontario resident","Non-exempt assets at or under $40,000 for a single person, or $50,000 for a couple","In financial need, based on your income, assets, living expenses, family size and shelter costs","Meet the ODSP definition of a person with a disability, or be a member of a prescribed class" ],"note":"The ODSP definition of disability: a substantial mental or physical impairment that is continuous or recurrent and is expected to last one year or more, whose direct and cumulative effect substantially restricts your ability to work, care for yourself, or take part in community life — verified by an approved health care professional."},"applyText":"Apply for ODSP","applyUrl":"https://www.ontario.ca/page/ontario-disability-support-program","source":"https://www.ontario.ca/page/ontario-disability-support-program","detail":{"about":"ODSP is Ontario's disability income support program. It pays monthly money toward basic needs and shelter and comes with health benefits such as prescription drugs and vision care. A single person can receive up to $1,436 a month for basic needs and shelter; you may receive more for a spouse or children, or for benefits such as transportation to medical appointments. Eligibility has two parts: you must be in financial need, and you must meet the program's definition of a person with a disability (decided through the Disability Determination Process) unless you are in a prescribed class.","aboutList":{"lead":"ODSP is Ontario's disability income support program.","items":["Pays monthly money toward basic needs and shelter — up to $1,436 a month for a single person.","You may receive more for a spouse or children, or for benefits such as transportation to medical appointments.","Comes with health benefits, including prescription drugs and vision care.","Eligibility has two parts: financial need, and either meeting the program's definition of a person with a disability or being a member of a prescribed class.","Rates are tied to inflation and adjusted each July; they rose 1.9% on July 1, 2026." ]},"steps":["Check the basic rules: 18 or older, an Ontario resident, in financial need, and within the asset limits","Apply online with one application covering you and the immediate family who live with you (about 20 to 30 minutes), by phone at 1-888-999-1142, or in person at your local ODSP office","A caseworker reviews your application and calls within 15 business days to book a verification appointment","Meet the caseworker to verify your information and provide your documents","Complete the Disability Determination Package with your health care professional and return it within 90 days — unless you are in a prescribed class" ],"documents":["Social insurance numbers (SIN) for everyone on the application","OHIP cards and birth certificates","Immigration papers, if they apply to you","Tax returns and banking information","Your housing costs and other expenses, such as child care and disability-related expenses" ],"tips":["If you need money now, one application covers both Ontario Works and ODSP. Ontario Works is assessed first. It can support you while your ODSP application is reviewed.","The application process may take a few months.","Return the completed Disability Determination Package to the Disability Adjudication Unit within 90 days. If you do not, the application is treated as withdrawn, unless you make a written request for an extension and it is approved.","If you get CPP-D or QPP-D, you are in a prescribed class and skip the disability adjudication step.","The Canada Disability Benefit does not count as income for ODSP.","The Disability Adjudication Unit sends you a letter within 90 business days. It tells you whether your disability qualified.","If no extra information is needed, your caseworker tells you within 15 business days whether you are financially eligible. If you are found not financially eligible, you have 30 days to ask ODSP to review your information again.","If you left ODSP and need to come back for financial help, you may be eligible for rapid reinstatement. It can make it faster and easier to start getting ODSP again, without a disability assessment. Contact your local ODSP office to find out if you are eligible.","Income support is paid monthly, on the last business day of each month. December payments may be available earlier in the month.","If you are interested in working, ask ODSP staff about employment-related supports in your community. Employment Ontario also offers training, skills and experience help." ],"phone":"1-888-999-1142 (TTY 1-800-387-5559)"}},{"id":"on-parking-permit","needsPractitioner":true,"name":"Accessible Parking Permit (Ontario)","level":"Ontario","category":"Parking","amount":"Free","summary":"A free permit to park in designated accessible spaces. It is issued to a person, not a vehicle. You can only use it when the permit holder is driving or riding in the vehicle. A regulated health professional certifies your condition on the application.","note":"The permit belongs to the person, not the car. You can only use it when the permit holder is in the vehicle. Misuse can bring a fine of up to $5,000. Each municipality sets its own parking privileges through local bylaws, so follow the rules where you park.","requires":["on","mobility" ],"eligibility":{"mode":"any","items":["Cannot walk without the help of a brace, cane, crutch, lower-limb prosthetic, wheelchair, or another person","Lung disease severe enough that forced expiratory volume is under one litre in one second","Portable oxygen is a medical necessity","Cardiovascular disease at Class III or Class IV functional capacity","Severely limited in the ability to walk by an arthritic, neurological, musculoskeletal, or orthopaedic condition","Visual acuity of 20/200 or poorer in the better eye with corrective lenses, or a maximum field of vision using both eyes with a diameter of 20 degrees or less","Mobility is severely limited by one or more conditions or functional impairments" ],"note":"A regulated health professional must certify one of these on your application: a physician, nurse practitioner (Extended Class), physiotherapist, occupational therapist, chiropractor, or podiatrist (chiropodist)."},"applyText":"Apply through ServiceOntario","applyUrl":"https://www.ontario.ca/page/get-accessible-parking-permit","source":"https://www.ontario.ca/page/get-accessible-parking-permit","detail":{"about":"The Ontario Accessible Parking Permit (APP) lets you park in designated accessible spaces. It is issued to a person, not a vehicle, so the named holder must be the driver or a passenger. There is no cost to get, renew, or replace it. Each municipality sets its own parking privileges through local bylaws, so always follow the rules where you park.","aboutList":{"lead":"The Ontario Accessible Parking Permit (APP) lets you park in designated accessible spaces.","items":["It is issued to a person, not a vehicle, so it can only be used when the permit holder is driving or riding in the vehicle.","There is no cost to get, renew, or replace it.","Each municipality sets its own parking privileges through local bylaws, so always follow the rules where you park.","Using the permit when the holder is not present could bring a fine of up to $5,000, and the permit may be seized." ]},"steps":["Check the eligible conditions to see whether you may qualify","Get the application form at any ServiceOntario centre or download it from ontario.ca","Complete the applicant section and have a regulated health professional certify your condition","Submit online with a ServiceOntario Account, by mail, or in person at a ServiceOntario centre","Display the permit with its number and expiry date visible on the dashboard or sun visor when parked" ],"documents":["A completed application with both the applicant section and the health-professional certification section","Acceptable identification" ],"tips":["There is no fee to get, renew, or replace the permit.","A permanent permit is valid for 5 years and renews without needing to be re-certified. Temporary and subject-to-change permits need re-certification to renew.","Municipalities set their own privileges (for example free or extended metered parking), so check your city's bylaws.","Travelling outside Ontario? If you hold a valid permit, you can get a traveller's permit. It lets you park the car you leave behind (for example at an Ontario airport or train station) while you take your regular permit on the trip." ]}},{"id":"niagara-transit-benefit-pass","name":"Niagara Transit Benefit Pass","level":"Niagara Region","category":"Transit","amount":"$50 monthly bus pass","summary":"A discounted $50 monthly bus pass from Niagara Region Transit. It is for Niagara residents on Ontario Works or ODSP, or who qualify as low income. Full-time post-secondary students are not eligible.","note":"Niagara Region must approve low-income applications before you buy a pass. It will not reimburse passes you already bought. The page does not give the low-income limits. Ask the Region how they apply to you.","requires":["niagaraRegion","niagaraTbpRoute","notFullTimePostSecondary" ],"eligibility":{"mode":"all","items":["You are a Niagara resident","You get Ontario Works or ODSP, or you qualify as a low-income individual or household","You are not a full-time post-secondary student" ],"note":"OW and ODSP recipients have qualified automatically since July 1, 2025; others apply for an income check."},"applyText":"Apply for the Transit Benefit Pass","applyUrl":"https://nrtransit.ca/fares/transit-benefit-pass/","source":"https://nrtransit.ca/fares/transit-benefit-pass/","detail":{"aboutList":{"lead":"This program gives eligible Niagara residents a discounted monthly bus pass.","items":["The pass costs $50 a month.","It is for individuals and families on Ontario Works, ODSP, or who qualify based on low-income criteria.","You pay for the pass yourself.","If you use the Transit app, the approval lets you buy the $50 monthly pass in the app each month for one year." ]},"steps":["If you get Ontario Works or ODSP, you already qualify. Get your monthly payment statement from the mail or online through MyBenefits","If you do not get OW or ODSP, apply online at owbenefits.niagararegion.ca. You can also call 905-641-9960 ext. 6072, fax 905-984-6759, or mail the Ontario Works Discretionary Benefit Team at 234 Bunting Rd., St. Catharines, L2R 6Z4","A staff member will contact you to review your application","If you applied on low income, wait for Niagara Region to approve you before you buy a pass. You then get a Transit Benefit Pass Approval Form for each eligible family member","Get verified in person with your ID and your benefit statement or approval form. For the Transit app, go to the St. Catharines Bus Terminal or the Welland Bus Terminal and give a unique email address. For a physical pass, go to a Transit Benefit Pass outlet","Pay $50 for the monthly pass" ],"documents":["One valid ID for each household member if you apply on low income: birth certificate, driver's licence, health card or citizenship document","Proof of income if you apply on low income, such as bank statements, pay stubs or pension stubs","If you get OW or ODSP: a recent benefit statement or proof of enrolment. OW clients can ask their caseworker for a proof of eligibility letter if they cannot get it online","If you applied on low income: the approved letter from Niagara Region's Social Assistance and Employment Opportunities office, or the Transit Benefit Pass Approval Form","A valid ID for each purchase. It must match your verification documents" ],"tips":["Apply and get approved before you buy a pass. The Region does not reimburse passes you already bought.","At a pass outlet, only the verified person can buy the pass. Bring your documents and ID each time.","Be ready to pay when you get verified.","In the Transit app, the pass is not available until that month's payment has been made.","For help, email info@niagaratransit.ca or call 1-833-678-5463." ],"phone":"905-641-9960 ext. 6072"}},{"id":"kingston-affordable-transit-pass","name":"Kingston Affordable Transit Pass","level":"Kingston","category":"Transit","amount":"Discounted monthly transit pass","summary":"A discounted, renewable monthly Kingston transit pass. You get it through the City's Municipal Fee Assistance Program (MFAP), which is income-based. You only need to apply once to MFAP.","note":"The page does not give the pass price. Funding is first-come, first-served until the yearly budget runs out. Ask the City about the price and Kingston Transit's fares and passes page.","requires":["kingston","kingstonMfapIncome" ],"eligibility":{"mode":"all","items":["MFAP compares your household income with its limit for your household size","You apply to the Municipal Fee Assistance Program (MFAP)" ],"note":"MFAP uses the after-tax Low-Income Measure plus 15 percent; the 2026 limits are in the tips below."},"applyText":"Apply for MFAP","applyUrl":"https://www.cityofkingston.ca/MFAP","source":"https://www.cityofkingston.ca/MFAP","detail":{"aboutList":{"lead":"MFAP gives low- and moderate-income households access to City services at no cost or a lower cost. The transit pass is one of them.","items":["You can get a discounted renewable monthly transit pass.","If you recently started a part-time or full-time job, the transit employment program gives a free two-month pass.","MFAP also covers other things, such as free access to fitness centres, public skates and public swims through SPARK." ]},"steps":["Compare your household income with the 2026 limits in the tips","Create a MyKingston account and apply online. You can also email mfap@cityofkingston.ca or apply in person at Housing and Social Services, 362 Montreal St.","See the City's Transit Fares and Passes page for the discounted monthly pass" ],"documents":["The page does not list documents. Ask the City what to bring" ],"tips":["2026 MFAP income limits (after tax): $34,793 for 1 person, $49,205 for 2, $60,263 for 3, $69,587 for 4, $77,800 for 5, $85,225 for 6, $92,054 for 7, $98,410 for 8, $104,380 for 9 and $110,020 for 10.","Funding is first-come, first-served, so apply early.","Questions: mfap@cityofkingston.ca or 613-546-2695 ext. 4906." ],"phone":"613-546-2695 ext. 4906"}},{"id":"halton-split","name":"Halton SPLIT transit subsidy (Burlington, Oakville, Milton)","level":"Halton Region","category":"Transit","amount":"Covers part of the cost of bus tickets or monthly passes","summary":"A Halton Region subsidy that pays part of your local bus tickets or monthly passes on Burlington, Oakville or Milton Transit. It is for Halton residents with a low income, including people on Ontario Works or ODSP.","note":"If you qualify, you are eligible for one year, then you re-apply. The page does not give the subsidy amount. Ask the Region what it covers for your age group and city.","requires":["haltonRegion","haltonSplitRoute" ],"eligibility":{"mode":"all","items":["You live in Halton","You are a student, adult or senior with a low income, or you get Ontario Works or ODSP" ],"note":"In Halton Hills the subsidy is for ActiVan or the Taxi Scrip Program instead of buses."},"applyText":"Apply for SPLIT","applyUrl":"https://www.halton.ca/For-Residents/Employment-and-Financial-Assistance/Subsidized-Passes-for-Low-Income-Transit-(SPLIT)","source":"https://www.halton.ca/For-Residents/Employment-and-Financial-Assistance/Subsidized-Passes-for-Low-Income-Transit-(SPLIT)","detail":{"aboutList":{"lead":"SPLIT helps Halton residents with low incomes pay for local travel.","items":["Use it for bus tickets or monthly passes from Burlington Transit, Oakville Transit or Milton Transit.","It also covers Handi-Van and Care-A-Van, but not GO Transit, taxis or ride-sharing.","You can transfer into Hamilton or Peel Region if you finish the trip within two hours." ]},"steps":["Check your eligibility with the SPLIT online tool. You do not need an account to check","Apply online with a Halton 311 account, or call 311","Send proof of address, income, date of birth and status in Canada within 10 business days, or the application is closed","Staff contact you if they need more information, then tell you if you qualify","Buy your pass or tickets: Burlington Transit at Burlington GO Station (2101 Fairview St.), Milton Town Hall (150 Mary St.) or Oakville Transit (430 Wyecroft Rd.)" ],"documents":["Proof of address for you and your spouse, such as a driver's licence or utility bill","A Notice of Assessment for every adult in your household","Proof of status in Canada and date of birth for you, your spouse and your children" ],"tips":["Only apply when your documents are ready. Missing documents close the application after 10 business days.","Upload documents online, mail them to Halton Regional Centre (1151 Bronte Road, Oakville) or drop them off in person." ]}},{"id":"belleville-recreation-fee-assistance","name":"Recreation Fee Assistance (Belleville)","level":"Belleville","category":"Recreation","amount":"25%, 50% or 75% off City recreation program fees","summary":"A discount on City of Belleville recreation programs and facility visits. Your household income sets the rate. Approval lasts from July 1 to June 30.","note":"Private, semi-private and low-ratio lessons, personal training, exam fees and add-ons are not covered. You renew every year. An appointment is needed only every other year unless your address or other details change.","requires":["on","belleville","bellevilleRecreationFeeAssistanceRoute" ],"eligibility":{"mode":"all","items":["You live in Belleville","Your total family income is within the City's chart limit for your family size" ],"note":"The City's chart gives the 75, 50 and 25 percent income limits for families of 1 to 7."},"applyText":"Apply for fee assistance","applyUrl":"https://www.belleville.ca/learn-and-play/recreation/recreation-guide-and-registration-information/recreation-fee-assistance/","source":"https://www.belleville.ca/learn-and-play/recreation/recreation-guide-and-registration-information/recreation-fee-assistance/","detail":{"aboutList":{"lead":"Approved households pay a lower rate on eligible City programs without reapplying for each one.","items":["Eligible programs may include camps, group swim and skate lessons, and aquafit sessions.","Eligible programs may also include session passes, drop-ins and facility memberships.","Aquatic leadership courses, such as Bronze Cross, may be eligible.","The rate is 25, 50 or 75 percent off, set by your income." ]},"steps":["Fill in the application online, or call 613-966-4632 to ask for a form.","Wait for an email with instructions to book an appointment.","Expect a call within 10 business days to confirm the appointment.","Bring your documents to the appointment.","Register for eligible programs at your approved rate." ],"documents":["Photo ID showing your address, for each household member 18 and over","Proof of income for everyone in the household, such as a Notice of Assessment, ODSP or Ontario Works statement","Proof of residency, such as a property tax bill or rental agreement" ],"tips":["To reapply, apply online or in person and hand in documents at the Quinte Sports & Wellness Centre." ],"phone":"613-966-4632"}},{"id":"chatham-kent-affordable-bus-pass","name":"Affordable Bus Pass (Chatham-Kent Transit)","level":"Chatham-Kent","category":"Transit","amount":"30-day unlimited urban transit pass for $41.99","summary":"A 30-day rolling pass with unlimited rides on urban routes for Chatham-Kent residents with a low family income. You can load 30, 60 or 90 days at a time.","note":"The pass also covers specialized transit in Chatham and Wallaceburg. The card cannot be passed to someone else.","requires":["on","chathamKent","chathamKentAffordableBusPassRoute" ],"eligibility":{"mode":"all","items":["You live in Chatham-Kent","Your yearly combined family income is at or below the Statistics Canada before-tax low-income measure" ],"note":"The limit depends on your family size, and ODSP clients can show current income statements."},"applyText":"Apply for the pass","applyUrl":"https://www.chatham-kent.ca/transit/fares/Pages/Affordable-Pass.aspx","source":"https://www.chatham-kent.ca/transit/fares/Pages/Affordable-Pass.aspx","detail":{"aboutList":{"lead":"The pass gives low-income residents a fixed price for unlimited urban bus rides.","items":["It starts the first time you scan it and runs for 30 days in a row.","It works on Chatham and Wallaceburg urban routes.","It also covers specialized transit." ]},"steps":["Fill in the application form.","Gather a tax notice and ID for each family member.","Submit everything to the Chatham-Kent Civic Centre.","Load 30, 60 or 90 days onto your card after you are approved." ],"documents":["A signed application form","A current Canada Revenue Agency Notice of Assessment for every family member with income","Identification for you and each family member, such as a birth certificate, license, passport or health card" ],"tips":["The pass costs $41.99.","The Affordable Bus Pass Policy on the transit site has more detail." ],"phone":"519-436-3233"}},{"id":"cornwall-fair","name":"Fee Assistance in Recreation, FAIR (Cornwall)","level":"Cornwall","category":"Recreation","amount":"75% of costs covered, up to $300 a year","summary":"The City covers 75 percent of swimming lessons, City sports and other recreation programs for low-income residents. You pay 25 percent. It also covers pool memberships and public skating passes.","note":"The $300 yearly cap applies. Each year on June 1 you send in the previous year's tax documents.","requires":["on","cornwall","cornwallFairRoute" ],"eligibility":{"mode":"all","items":["You live in the City of Cornwall","You are 18 or older to apply","Your yearly combined family income is at or below the Statistics Canada Low Income Cut-Off","You have not used up the yearly funding maximum" ]},"applyText":"Apply for FAIR","applyUrl":"https://www.cornwall.ca/en/recreation-community-supports/recreation-and-sports/fee-assistance-in-recreation/","source":"https://www.cornwall.ca/en/recreation-community-supports/recreation-and-sports/fee-assistance-in-recreation/","detail":{"aboutList":{"lead":"FAIR lowers what you pay for City recreation so cost is not a barrier.","items":["You pay only 25 percent of eligible costs.","Swimming lessons and City sports are included.","Pool memberships and public skating passes are included.","Support stops once you reach $300 for the year." ]},"steps":["Fill in the FAIR client application form.","Add ID for each family member and one proof of income.","Add proof that you live in Cornwall.","Email the full package to the City.","Send last year's documents again each June 1." ],"documents":["One photocopy of ID for each family member","One of these, showing your address: a Notice of Assessment for each adult, an Ontario Works or ODSP statement of deposit, a Canada Child Benefit notice, or a GIS notice","Proof of residency, such as a lease, utility bill or driver's licence" ],"tips":["Canadian Tire Jumpstart can also help with youth sports costs." ]}},{"id":"peterborough-recreation-subsidy","name":"Recreation Program Subsidy (Peterborough)","level":"Peterborough","category":"Recreation","amount":"$100 or $200 a year toward recreation registration","summary":"A yearly subsidy toward registration for sports, camps and recreation programs in Peterborough. People with a low income or on Ontario Works or ODSP can apply. Your income decides if you get $100 or $200.","note":"It covers registration fees only, not equipment or after-school programs. Programs outside City limits are not covered.","requires":["on","peterborough","peterboroughRecreationSubsidyRoute" ],"eligibility":{"mode":"any","items":["You live in Peterborough and your household income is under the low-income cut-off chart","You live in Peterborough and receive Ontario Works or ODSP" ],"note":"The limit is $39,668 for a household of up to five for the full $200, and $39,669 to $43,993 for $100."},"applyText":"Apply for the subsidy","applyUrl":"https://www.peterborough.ca/recsubsidy","source":"https://www.peterborough.ca/recsubsidy","detail":{"aboutList":{"lead":"The subsidy is paid straight to the program provider, or refunded if you already paid.","items":["Children aged 17 and under can get up to $200 a year each.","Adults can get up to $200 a year for programs at City facilities.","Sports leagues, camps, dance, martial arts and skating lessons count.","You can apply for several programs and people at once." ]},"steps":["Check your household income against the chart.","Upload your documents in the online application.","Register for your programs, then pay anything above your subsidy.","For other groups, give them the Verification of Subsidy letter." ],"documents":["Notice of Assessment or Canada Child Tax Benefit statement for each adult, since pay stubs are not accepted","Statement of Assistance for anyone on Ontario Works or ODSP","Proof of a City of Peterborough address","The program name and start date" ],"tips":["To be refunded, apply within 30 days of paying.","Staff can help with your application by email or phone." ],"phone":"705-742-0050 ext. 1574"}},{"id":"peterborough-ow-odsp-transit-pass","name":"Subsidized City Bus Pass (Peterborough, OW and ODSP)","level":"Peterborough","category":"Transit","amount":"30-day City bus pass for $49","summary":"A subsidized monthly Peterborough Transit pass for adults on Ontario Works and for people on ODSP. A 30-day pass costs $49.","note":"Ontario Works clients may be eligible if they do not get transportation money from their Case Manager.","requires":["on","peterborough","peterboroughOwOdspTransitPassRoute" ],"eligibility":{"mode":"any","items":["You are an adult on Ontario Works in the City or County and get no travel money from your Case Manager","You are an ODSP client living in the City or County of Peterborough" ]},"applyText":"See how to get the pass","applyUrl":"https://peterborough.ca/recreation-culture-social-services/social-services/ontario-works/transportation-help","source":"https://peterborough.ca/recreation-culture-social-services/social-services/ontario-works/transportation-help","detail":{"aboutList":{"lead":"The pass lowers the price of monthly City bus travel for people on Ontario Works or ODSP.","items":["You buy it in person at the Peterborough Transit bus terminal.","Both city and county residents on these programs can use it." ]},"steps":["Take your statement of assistance for the current month and personal ID.","Go to the Peterborough Transit bus terminal at 190 Simcoe St.","Buy the 30-day pass for $49." ],"documents":["Your Ontario Works or ODSP statement of assistance for the current month","Personal identification" ],"tips":["Ontario Works clients can ask their Case Manager about the pass." ],"phone":"705-748-8830"}},{"id":"brantford-recreation-subsidy","name":"Recreation Financial Assistance (Brantford)","level":"Brantford","category":"Recreation","amount":"25%, 50% or 75% of program fees paid, or 100% on assistance","summary":"The City pays part of drop-in and registered program fees for children and youth 17 and under. The share depends on family size and gross income. Ontario Works, ODSP and refugee-status families get 100% with documents.","note":"Help is limited to two programs per person per season and two weeks of summer camp. Funds and programs must be available. Some restrictions apply. It is free to apply.","requires":["on","brantford","brantfordRecreationSubsidyRoute" ],"eligibility":{"mode":"any","items":["Your family's gross annual income falls within the City's chart for your family size","You are on Ontario Works or ODSP, or your family has refugee status" ],"note":"The program is for children and youth 17 and under."},"applyText":"Apply for financial assistance","applyUrl":"https://www.brantford.ca/en/things-to-do/recreational-programs-financial-assistance.aspx","source":"https://www.brantford.ca/en/things-to-do/recreational-programs-financial-assistance.aspx","detail":{"aboutList":{"lead":"The City pays a share of fees, based on family size and income.","items":["The City pays 75% if gross income is $0 to $22,000 for a family of 1 or 2.","The share drops to 50% and then 25% at higher income bands in the chart.","Bands run up to $51,900 for a family of 6 or more.","It covers most drop-in and registered programs, if funds and programs are available." ]},"steps":["Check the financial assistance chart for your family size","Fill out the online application, or apply at the front reception desk","Pay your share of the fee when you register" ],"documents":["On Ontario Works or ODSP: a current pay stub and Child Tax Benefit showing the children's names","Others: an income tax form or Notice of Assessment, and a current pay stub","Or a pay stub and Child Tax Benefit, or an Employment Insurance stub and Child Tax Benefit" ],"tips":["Assistance also depends on whether your family already got help this registration period.","The Arnold Anderson Sport Fund is separate. It gives youth up to $350, and the City does not approve it." ],"phone":"519-759-4150"}},{"id":"cornwall-community-bus-pass","name":"Community Bus Pass (Cornwall)","level":"Cornwall","category":"Transit","amount":"Affordable bus pass; 175 passes available","summary":"An affordable Cornwall Transit pass for people who get ODSP or Ontario Works. There are 175 passes, given first come, first served. The pass also works on Specialized Service if you have qualified for it.","note":"You need documents each time you buy a pass. The page does not give the price. Contact Cornwall Transit to ask.","requires":["on","cornwall","cornwallCommunityBusPassRoute" ],"eligibility":{"mode":"any","items":["You get benefits from the Ontario Disability Support Program","You get Ontario Works assistance" ]},"applyText":"Buy a pass at the transit office","applyUrl":"https://www.cornwall.ca/en/public-safety-transportation/transit/fares-and-passes/community-passes/","source":"https://www.cornwall.ca/en/public-safety-transportation/transit/fares-and-passes/community-passes/","detail":{"aboutList":{"lead":"A lower-cost pass for people on ODSP or Ontario Works.","items":["Qualified Specialized Service users can use it on that service too." ]},"steps":["Go to the Cornwall Transit office at 863 Second St W","Show your photo ID and proof of benefits","Buy the pass" ],"documents":["Photo ID","An original or photocopied Ontario Works or ODSP cheque stub, or a drug or dental card" ],"tips":["Bring proof every time you buy a pass." ],"phone":"613-930-2787"}},{"id":"sarnia-cnib-pass","name":"Annual CNIB Pass (Sarnia Transit)","level":"Sarnia","category":"Transit","amount":"$36 per the fare table ($35.25 per a page note); regular annual pass is $1,065","summary":"A discounted annual Sarnia Transit bus pass for riders with a valid CNIB card. The 2026 fare table says $36 but a note on the page says $35.25. Passes are sold at City Hall, Customer Service Department.","note":"A note on the page lists the price as $35.25, while the fare table says $36. Ask Customer Service to confirm. Refunds are not available for transit passes.","requires":["on","sarnia","sarniaCnibPassRoute" ],"eligibility":{"mode":"all","items":["You are a rider with a valid CNIB card" ]},"applyText":"Contact Customer Service for the pass","applyUrl":"https://www.sarnia.ca/living-here/getting-around/sarnia-transit/transit-fares/","source":"https://www.sarnia.ca/living-here/getting-around/sarnia-transit/transit-fares/","detail":{"aboutList":{"lead":"A low-cost yearly bus pass for CNIB cardholders.","items":["It is a full year pass, against $1,065 for the regular annual pass.","Children 12 and under already ride free." ]},"steps":["Contact Customer Service about the CNIB pass","Bring your valid CNIB card to City Hall, 255 Christina Street North","Buy the pass" ],"documents":["A valid CNIB card" ],"tips":["Smartcard replacement costs $7.15." ],"phone":"519-332-0330 ext. 3131"}},{"id":"on-child-benefit","name":"Ontario Child Benefit","level":"Ontario","category":"Money (for parents)","amount":"Up to $1,760 per child each year","summary":"A monthly payment for low-income to moderate-income families to help with the cost of raising children. The Canada Revenue Agency sets the amount for each family.","note":"There is no separate application. The Canada Child Benefit application also assesses you, and you must file taxes each year.","requires":["on","onChildBenefitRoute" ],"eligibility":{"mode":"all","items":["You are a low-income to moderate-income family with children in your care.","You apply for the Canada Child Benefit through the Canada Revenue Agency.","You file your taxes every year, even if you have no income to declare." ],"note":"The amount depends on your family net income and the number of children under 18 in your care."},"applyText":"Apply for the Canada Child Benefit","applyUrl":"https://www.ontario.ca/page/ontario-child-benefit","source":"https://www.ontario.ca/page/ontario-child-benefit","detail":{"aboutList":{"lead":"The Ontario Child Benefit helps families with the cost of raising children, including a child with a disability.","items":["Pays up to $1,760 per child per year, in monthly payments, if you are eligible.","The amount depends on your adjusted family net income on your annual tax return.","The number of children in your care who are under 18 also affects the amount.","The Canada Revenue Agency runs the benefit for Ontario." ]},"steps":["Send in your Canada Child Benefit application.","Every year, file your taxes, even with nothing to declare.","Wait for the Canada Revenue Agency to assess you for the Ontario Child Benefit and set your monthly payment." ],"documents":["Your income tax return each year" ],"tips":["Use the Canada Revenue Agency benefit calculator to see how much you may receive.","If you need help with your taxes, the page points to free tax help and free tax clinics." ],"phone":"1-800-387-1193"}},{"id":"on-dso-adult-services","name":"Developmental Services Ontario adult services","level":"Ontario","category":"Daily living supports","amount":"Services and supports, based on your assessed needs","summary":"Developmental Services Ontario (DSO) is the way in to provincially funded services for adults with a developmental disability. Staff help you apply, assess your needs and connect you with available supports.","note":"Going through the application does not guarantee that you will receive services right away. Your risk-based priority is compared with everyone else waiting.","requires":["on","age18plus","developmental","onDsoAdultServicesRoute" ],"eligibility":{"mode":"all","items":["You have a developmental disability, confirmed by a registered psychologist or psychological associate.","You are at least 18 years old.","You live in Ontario." ],"note":"These general rules come from the 2008 Act on social inclusion of people with developmental disabilities."},"applyText":"Contact Developmental Services Ontario","applyUrl":"https://www.ontario.ca/page/programs-and-services-adults-developmental-disabilities-ontario","source":"https://www.ontario.ca/page/programs-and-services-adults-developmental-disabilities-ontario","detail":{"aboutList":{"lead":"This page explains the services and supports for adults with a developmental disability and their families.","items":["Helps you live, work and take part in your community.","Includes Passport funding, specialized clinical supports and Adult Protective Service Worker help.","Includes residential supports such as group living, supported independent living and the Host Family Program.","You can use part of your Passport funding for person-directed planning." ]},"steps":["Contact your local Developmental Services Ontario office to apply.","Meet with a DSO assessor for the application for developmental services and supports (ADSS).","Meet again for the Supports Intensity Scale for adults (SIS-A), which measures the supports you need.","Staff use a province-wide tool to score your level of risk and set your priority for services." ],"documents":["Confirmation of your developmental disability from a registered psychologist or psychological associate" ],"tips":["Each of the two meetings may take a couple of hours.","Family caregivers can share their needs in the application.","Private providers are not government-funded; check what they offer and charge before you choose." ]}},{"id":"on-enhanced-respite","name":"Enhanced Respite for medically fragile children","level":"Ontario","category":"Home support","amount":"Up to $4,213 per child each fiscal year","summary":"Pays families back for respite care for a child under 18 who is medically fragile or technology dependent and needs care 24 hours a day. You claim the cost of covered respite services or supports.","note":"The services and supports covered are the same as those covered by the Special Services at Home program.","requires":["on","child","onEnhancedRespiteRoute" ],"eligibility":{"mode":"all","items":["Your child is under 18 years of age.","Your child lives at home.","Your child needs intensive care and constant monitoring on a 24-hour basis.","Your child is medically fragile or technology dependent, in one of the listed ways." ],"note":"Listed ways include a ventilator, dialysis, IV drugs, tracheotomy care, suctioning, oxygen or tube feeding."},"applyText":"Contact your ministry regional office","applyUrl":"https://www.ontario.ca/page/family-support-and-respite-children-and-youth-special-needs","source":"https://www.ontario.ca/page/family-support-and-respite-children-and-youth-special-needs","detail":{"aboutList":{"lead":"Enhanced Respite gives families a break from round-the-clock care of a medically fragile child.","items":["Gives back the cost of covered respite when you make a claim.","Respite can be in your home or outside your home, from local agencies.","Funding is for families caring for a child who depends on medical or technological equipment.","Extra funding was added on July 1, 2022 to support personal support worker wages." ]},"steps":["Contact the ministry regional office nearest to you to apply.","Arrange respite care with a local agency in or outside your home.","Make a claim to get the cost of covered respite back." ],"documents":[ ],"tips":["Ask the regional office which respite supports are covered before you pay.","The same page also covers Special Services at Home, and Assistance for Children with Severe Disabilities." ]}},{"id":"on-gains","name":"Guaranteed Annual Income System (GAINS)","level":"Ontario","category":"Income support","amount":"Up to $92 a month for the 2026 benefit year (July 1, 2026 to June 30, 2027)","summary":"A monthly, non-taxable payment for Ontario seniors with low income. It is paid on top of any federal OAS and GIS payments you may get.","note":"If you had no private income in 2025, you get the maximum amount. Different income limits apply if your spouse is under 65 or cannot get Old Age Security.","requires":["on","age65plus","onGainsRoute" ],"eligibility":{"mode":"all","items":["You are 65 years or older.","You have been a Canadian resident for 10 years or more.","You have lived in Ontario for 12 months, or for 20 years in total since age 18.","You receive the federal Old Age Security (OAS) pension and Guaranteed Income Supplement (GIS).","Your private income is up to $4,416 (single) or $8,832 (couple)." ],"note":"Private income can include a workplace pension, the Canada Pension Plan and bank interest."},"applyText":"File your tax return or complete a GIS application","applyUrl":"https://www.ontario.ca/page/guaranteed-annual-income-system-payments-seniors","source":"https://www.ontario.ca/page/guaranteed-annual-income-system-payments-seniors","detail":{"aboutList":{"lead":"GAINS tops up the income of low-income seniors in Ontario.","items":["Paid about the 25th of each month, from July to June.","Your payment can change during the year if your private income or marital status changes.","The benefit year runs from July 1 to June 30 of the next year.","Tables on the page show your amount by age and marital status." ]},"steps":["If you already get Old Age Security and the Guaranteed Income Supplement, you do not have to apply.","File your income tax return every year by April 30, even with no income to report.","Or complete a Guaranteed Income Supplement application and send it to your nearest Service Canada office.","Sign up for direct deposit through Service Canada." ],"documents":["Your income tax and benefit return" ],"tips":["If you disagree with a decision, contact the Ontario Ministry of Finance.","You can file a Notice of Objection within 90 days of the written decision being mailed." ],"phone":"1-800-277-9914"}},{"id":"on-healthy-smiles","name":"Healthy Smiles Ontario","level":"Ontario","category":"Health (for children)","amount":"Free preventive, routine and emergency dental care for children 17 and under","summary":"A government-funded dental program for children and youth 17 and under from low-income households. It pays for preventive, routine and emergency dental services.","note":"Cosmetic dentistry such as teeth whitening and braces is not covered. Your child may still qualify if they already have dental insurance.","requires":["on","child","onHealthySmilesRoute" ],"eligibility":{"mode":"any","items":["Your child gets Temporary Care Assistance or Assistance for Children with Severe Disabilities.","You or your family get Ontario Works or the Ontario Disability Support Program.","Your child is 17 or under, lives in Ontario, and your family net income is at or under the table limit." ],"note":"As of July 1, 2026 the limit is $29,065 for 1 child, $31,265 for 2 children and $33,465 for 3 children."},"applyText":"Enrol in Healthy Smiles Ontario","applyUrl":"https://www.ontario.ca/page/get-dental-care","source":"https://www.ontario.ca/page/get-dental-care","detail":{"aboutList":{"lead":"Healthy Smiles Ontario pays for dental care for eligible children and youth.","items":["Covers check-ups, cleaning, fillings, x-rays, scaling and tooth extraction.","Covers urgent or emergency care, including a toothache.","Covers a child for up to one benefit year (August 1 to July 31) or until their 18th birthday.","Children in kindergarten and Grade 2 at public elementary schools can get free dental screening." ]},"steps":["Check whether your child is enrolled automatically.","If not, apply online or by mail with the General Application Form.","Wait for the dental card to arrive by mail.","Show the card to your dental provider at each visit." ],"documents":["Your child's date of birth","A valid Ontario address","Your Social Insurance Number or Temporary Taxation Number","Proof you filed taxes in the previous year (or a guarantor form if you did not file)" ],"tips":["Ask your dentist if they take Healthy Smiles Ontario; your local public health unit can help find one.","Emergency or essential care lasts 6 months and a child can use it a maximum of 3 times in their lifetime.","Families on Ontario Works in a First Nations community are not enrolled automatically and must apply by mail." ],"phone":"1-844-296-6306"}},{"id":"on-ontario-works","name":"Ontario Works","level":"Ontario","category":"Income support","amount":"Up to $733 a month for basic needs and shelter if you are single","summary":"Money for living costs such as food and rent, plus health benefits, for people in financial need. In most cases you take part in employment-related activities to get the money.","note":"The Canada Disability Benefit is exempt as income and does not affect your Ontario Works eligibility or payment. You may get more for family members or other benefits.","requires":["on","onOntarioWorksRoute" ],"eligibility":{"mode":"all","items":["You need financial assistance for food and housing.","You are in financial need." ],"note":"A worker checks your income and assets; if found not eligible, you have 30 days to ask for a review."},"applyText":"Apply for Ontario Works","applyUrl":"https://www.ontario.ca/page/ontario-works","source":"https://www.ontario.ca/page/ontario-works","detail":{"aboutList":{"lead":"Ontario Works helps people in financial need with living costs.","items":["Pays money toward living expenses, including food and rent.","Includes health benefits for you and your eligible family members.","You may get more if you have a spouse or child.","You may get extra money, for example for transport to medical appointments." ]},"steps":["Apply online (20 to 30 minutes), by phone, or at your local Ontario Works office.","An intake worker reviews your application and may ask for more documents.","You are told within four business days if you are approved and how much you may receive.","Your Ontario Works office schedules an appointment to make a plan for employment-related activities." ],"documents":["Social insurance numbers, if applicable","OHIP cards","Birth certificates","Immigration papers","Tax returns","Banking information and bank statements","Proof of income, shelter costs and Ontario residency" ],"tips":["One application covers you and the immediate family who live with you.","All family members on the application should be with you when you start, so they can consent.","A plan for work activities may be waived for reasons such as an illness or caregiving responsibilities.","If you have a disability, one application can be used for Ontario Works or the Ontario Disability Support Program." ],"phone":"1-888-999-1142"}},{"id":"on-seniors-dental","name":"Ontario Seniors Dental Care Program","level":"Ontario","category":"Health","amount":"Free routine dental care","summary":"Free, routine dental care for low-income Ontario seniors 65 or older. It covers check-ups, fillings, x-rays, tooth removal and treatment for infection, pain and gum disease.","note":"Coverage ends on July 31 every year. Dentures are partially covered; some procedures have limits. You may still qualify if you also qualify for the Canadian Dental Care Plan.","requires":["on","age65plus","onSeniorsDentalRoute" ],"eligibility":{"mode":"all","items":["You are 65 years of age or older.","You live in Ontario.","Your annual net income is $25,480 or less (single), or $42,290 or less (couple, combined).","You have no other dental benefits, apart from the Canadian Dental Care Plan." ],"note":"Other benefits include private insurance, Ontario Works and the Ontario Disability Support Program."},"applyText":"Apply to the Ontario Seniors Dental Care Program","applyUrl":"https://www.ontario.ca/page/dental-care-seniors","source":"https://www.ontario.ca/page/dental-care-seniors","detail":{"aboutList":{"lead":"The program pays for routine dental care for low-income seniors.","items":["Covers check-ups, scaling, fluoride and polishing.","Covers repairing broken teeth and cavities, and x-rays.","Covers removing teeth or abnormal tissue, with anesthesia.","Covers treating infection, pain and gum conditions." ]},"steps":["Apply online or by mail.","If you and your spouse both apply, send two separate applications.","Wait for the welcome package and dental card by mail.","Show your card at each dental visit." ],"documents":["Your date of birth","A valid Ontario address","Your Social Insurance Number or Temporary Taxation Number","Proof you filed taxes last year (or a guarantor form if you did not file)" ],"tips":["Your local public health unit can help you apply and find where to get care.","Care is available through public health units and partner community health centres.","Most clients are re-checked automatically each year; you are told by mail if you must re-apply." ],"phone":"1-833-207-4435"}},{"id":"on-trillium-benefit","name":"Ontario Trillium Benefit","level":"Ontario","category":"Money & taxes","amount":"For the 2026 benefit year: up to $1,307 (age 18 to 64) or $1,488 (65 or older) from the energy and property tax credit, plus other credits","summary":"A tax-free payment that helps low-to-moderate income Ontario residents pay for energy costs, sales tax and property tax. It combines three credits, and you need to be eligible for at least one.","note":"You apply by filing your tax return and the ON-BEN form, even with no income. The Canada Revenue Agency decides if you are eligible. The last day to file is April 30.","requires":["on","onTrilliumBenefitRoute" ],"eligibility":{"mode":"any","items":["Northern Ontario Energy Credit: you lived in Northern Ontario on December 31, 2025.","Ontario Energy and Property Tax Credit: you lived in Ontario on December 31, 2025.","Ontario Sales Tax Credit: you are an Ontario resident, 19 or older, or have a partner or child." ],"note":"Each credit also has conditions, such as age, family status, and rent or property tax paid in 2025."},"applyText":"File your tax return with the ON-BEN form","applyUrl":"https://www.ontario.ca/page/ontario-trillium-benefit","source":"https://www.ontario.ca/page/ontario-trillium-benefit","detail":{"aboutList":{"lead":"The three credits are paid together for the 2026 benefit year (July 2026 to June 2027).","items":["Northern Ontario Energy Credit: up to $189 if single, up to $290 for families.","Energy and Property Tax Credit: up to $290 if you live on a reserve or in a public long-term care home.","Sales Tax Credit: up to $378, plus up to $378 for a spouse and each dependent child under 19.","Amounts depend on your age, income, residence, family size and rent or property tax." ]},"steps":["File your income tax and benefit return every year.","Fill out and enclose the ON-BEN application form from your tax package.","The Canada Revenue Agency tells you if you are entitled to the credits.","Choose how you want to be paid if you qualify for more than $500." ],"documents":["Your income tax return","Form ON-BEN" ],"tips":["If you are turning 18 before June 2027, file your tax return to be considered.","If you cannot prepare your return yourself, the Community Volunteer Income Tax Program may help.","If you file late, you still receive the benefit, but your payments may be delayed.","Beware of text messages claiming you are owed a payment; the Government of Ontario will not send them." ]}},{"id":"on-drug-benefit","name":"Ontario Drug Benefit","level":"Ontario","category":"Health","amount":"Covers most of the cost of more than 5,900 listed drugs; what you pay (deductible and/or co-payment of up to $2 or $6.11 a prescription) depends on how you qualify","summary":"Covers most of the cost of prescription drugs on the Ontario Drug Benefit Formulary. You can qualify at 65, or sooner through social assistance, home care and other routes.","note":"Prescriptions must be filled in an Ontario pharmacy, and you may need to show your Ontario health card. Some drugs are Limited Use or covered only through the Exceptional Access Program.","requires":["on","onDrugBenefitRoute" ],"eligibility":{"mode":"any","items":["You are 65 or older (you join automatically the month after you turn 65).","You get benefits from Ontario Works or the Ontario Disability Support Program.","You get professional home and community care services.","You live in a long-term care home or a Community Home for Opportunity.","You are 24 or younger and not covered by private insurance.","You are enrolled in the Trillium Drug Program." ],"note":"Some groups also need an Ontario health card number."},"applyText":"Learn how to get Ontario Drug Benefit coverage","applyUrl":"https://www.ontario.ca/page/get-coverage-prescription-drugs","source":"https://www.ontario.ca/page/get-coverage-prescription-drugs","detail":{"aboutList":{"lead":"The program pays most of the cost of listed prescription drugs.","items":["Covers more than 5,900 drugs on the Formulary and almost 1,500 more through the Exceptional Access Program.","Seniors pay the first $100 each program year, then a small co-payment per prescription.","Seniors in the Seniors Co-Payment Program pay no deductible and up to $2 a prescription.","Ontario Works and ODSP recipients pay up to $2 for each drug, with no deductible." ]},"steps":["If you are turning 65, watch for the letter about 3 months before your birthday.","Go to your pharmacy on the first day of the month after you turn 65.","If you qualify another way, ask your caseworker, care coordinator or pharmacist how it works.","If you paid for a covered drug, submit your receipts online or by mail for a refund." ],"documents":["Ontario health card","Official prescription receipt signed by a pharmacist (for refunds)" ],"tips":["After the first $100, seniors pay up to $6.11 per prescription.","The first-year deductible for seniors can be lower than $100, depending on your birth month.","If you are 24 or younger and in some groups, you do not pay the $2.","The program also covers allergy shots, epinephrine injectors, some diabetes testing strips and some nutrition products." ]}},{"id":"on-home-community-care","name":"Home and community care (Ontario Health atHome)","level":"Ontario","category":"Home support","amount":"Government pays for home care if you qualify; community support services may have a co-payment","summary":"Care at home for people of all ages who need it, including seniors and people with disabilities. It also covers respite so a caregiver can take a break. Ontario Health atHome decides what you are eligible for.","note":"If you qualify, the Ontario government pays for home care. Community support services can have a client co-payment. Respite at home is fully covered if you qualify, otherwise other providers charge a fee.","requires":["on","onHomeCommunityCareRoute" ],"eligibility":{"mode":"all","items":["You need care at home, at school or in the community.","Ontario Health atHome assesses that you are eligible for the services.","You have a valid Ontario health card (for respite at home).","Your home is properly equipped for the services you need (for respite at home)." ],"note":"Homemaking needs personal support, or constant supervision due to cognitive impairment or acquired brain injury."},"applyText":"Call Ontario Health atHome","applyUrl":"https://www.ontario.ca/page/homecare-seniors","source":"https://www.ontario.ca/page/homecare-seniors","detail":{"aboutList":{"lead":"Ontario Health atHome provides home care and links you to community support services.","items":["Nursing, physiotherapy, occupational therapy, speech-language pathology, social work and healthy eating help.","Personal support such as bathing, dressing, eating and toileting.","Homemaking such as cleaning, laundry, shopping and meal planning.","Respite care at home, in a long-term care home for a short stay, or at an adult day program." ]},"steps":["Call Ontario Health atHome or use their map to find care near you.","A case manager or care coordinator assesses your needs and eligibility, and may visit your home.","If you are eligible, you and anyone you choose make a home care plan.","Your care is scheduled with Ontario Health atHome or a service provider." ],"documents":["Ontario health card" ],"tips":["A short respite stay in long-term care can be up to 60 days, and no more than 90 days in a calendar year.","Adult day programs need a referral from Ontario Health atHome and usually charge a fee per day.","If you are refused, you can complain to Ontario Health atHome or appeal to the Health Services Appeal and Review Board." ],"phone":"1-833-515-1234"}},{"id":"on-northern-health-travel-grant","name":"Northern Health Travel Grant","level":"Ontario","category":"Health","amount":"41 cents per km (round trip) plus $175 to $1,150 for lodging (service dates on or after December 1, 2024)","summary":"Helps Northern Ontario residents pay part of the cost of travelling at least 100 km one way for specialist care. It does not cover all travel costs, such as meals or taxis.","note":"Send your application to the Ministry of Health within 12 months of the treatment date. You need a separate application for each round trip, and original receipts for lodging and tickets.","requires":["on","onNorthernHealthTravelGrantRoute" ],"eligibility":{"mode":"all","items":["You are an OHIP-insured Ontario resident on the date of treatment.","Your home is in a listed Northern Ontario district.","You are referred for specialist care or a procedure at a ministry-funded health-care facility.","You travelled at least 100 km one way to the nearest specialist or facility that could help." ],"note":"Algoma, Cochrane, Kenora, Manitoulin, Nipissing, Parry Sound, Rainy River, Sudbury, Thunder Bay, Timiskaming."},"applyText":"Apply online for the Northern Health Travel Grant","applyUrl":"https://www.ontario.ca/page/northern-health-travel-grant-program","source":"https://www.ontario.ca/page/northern-health-travel-grant-program","detail":{"aboutList":{"lead":"The grant pays part of the cost of long trips for specialist medical care.","items":["Pays 41 cents per km, based on the round-trip distance, for car, air, bus or rail.","Pays a lodging allowance of $175 to $1,150 for medically necessary nights, if you paid for official lodging.","A companion of a hospitalized patient can get a lodging allowance if aged 16 or older and meeting the conditions.","Not covered: care linked to a WSIB claim, or travel paid by another program or employer." ]},"steps":["Check that you meet the rules and that the care is not available closer.","Ask the specialist or facility to complete their part of the form.","Apply online, or by mail with the paper form.","Include original receipts for lodging and for air, bus or rail tickets." ],"documents":["Original itemized lodging receipts with the patient name, dates and fee","Original tickets, receipts or itinerary for air, bus or rail","Specialty-Service Provider Form (online application)" ],"tips":["Telemedicine may let you see a specialist without travelling; ask your provider.","Do not send meal or taxi receipts.","Do not photograph documents for the online form; scan them to PDF, because photos are often too large.","If patients share one car, only one grant is paid for the round trip." ]}},{"id":"on-odsp-employment-supports","name":"ODSP employment supports and earnings rules","level":"Ontario","category":"Employment","amount":"Earn up to $1,000 a month without losing ODSP income support; Work-Related Benefit up to $100 per family member","summary":"If you get Ontario Disability Support Program (ODSP) income support, you can work and keep your support and benefits. Extra benefits help with child care and start-up costs for a job, training or a business.","note":"You must report all earnings every month, even if they are exempt. If you miss a reporting deadline, your payments and benefits may stop temporarily.","requires":["on","onOdspEmploymentSupportsRoute" ],"eligibility":{"mode":"all","items":["You get ODSP income support.","You want to work, train or start your own business." ],"note":"Family members can qualify for some benefits, with different age and schooling rules for each benefit."},"applyText":"Contact your ODSP caseworker","applyUrl":"https://www.ontario.ca/page/working-and-earning-ontario-disability-support-program","source":"https://www.ontario.ca/page/working-and-earning-ontario-disability-support-program","detail":{"aboutList":{"lead":"ODSP lets you earn money while keeping your income support.","items":["Since February 1, 2023: up to $1,000 a month in net earnings with no reduction.","After the first $1,000, 25% of net earnings is also exempt.","The Work-Related Benefit gives up to $100 for each eligible family member who earns money.","The Employment and Training Start Up Benefit gives up to $500 in a 12-month period.","Up-front child care: the full cost of licensed care, or up to $600 per child in 12 months if unlicensed." ]},"steps":["Tell your caseworker about the money you and your family earn.","Report your earnings each month through MyBenefits, the phone system, or the Employment/Training Income Report form.","Return the report by the seventh day of the following month.","Contact your caseworker to ask for the child care or start-up benefits, and send proof." ],"documents":["Pay stubs","Business income and expense records, if self-employed","Letter of employment or training registration","Proof you need to pay for child care in advance" ],"tips":["Report both gross and net pay.","If you earn nothing that month, put $0 on the form and still send it in.","If you stop working, tell your caseworker right away.","You do not need proof of employment costs to get the Work-Related Benefit; it is added automatically." ]}},{"id":"on-odsp-health-benefits","name":"ODSP health and disability benefits (including Special Diet Allowance)","level":"Ontario","category":"Health","amount":"Varies by benefit; Special Diet Allowance up to $250 a month per person; Guide Dog Benefit $84 a month per dog","summary":"Health and disability benefits for people who get Ontario Disability Support Program (ODSP) income support, and their families. They help with drugs, dental, vision, assistive devices, medical travel and special diets.","note":"Many benefits need approval from your ODSP office or an approved health professional before you buy. Ask first so you are not left paying the cost yourself.","requires":["on","onOdspHealthBenefitsRoute" ],"eligibility":{"mode":"all","items":["You get ODSP income support.","For some benefits, an approved health professional must complete a form.","For the Special Diet Allowance, you or a family member has a listed medical condition." ],"note":"People who leave ODSP may get the Extended or Transitional Health Benefit, with their own rules."},"applyText":"Contact your local ODSP office","applyUrl":"https://www.ontario.ca/page/ontario-disability-support-program-health-and-disability-benefits","source":"https://www.ontario.ca/page/ontario-disability-support-program-health-and-disability-benefits","detail":{"aboutList":{"lead":"The benefits cover many costs linked to a disability or medical condition.","items":["Prescription drugs on the Formulary, with a co-payment of up to $2 per prescription if you are 25 or older.","Basic dental for you and your spouse; children under 18 get Healthy Smiles Ontario.","Eye exams once every two years and eyeglasses once every three years, if OHIP does not cover them.","Medical transportation, if you spend $15 or more a month, and medically necessary supplies.","Help with hearing aids, mobility device repairs and costs the Assistive Devices Program does not cover.","Special Diet Allowance: up to $250 a month for each member with an approved medical condition.","Pregnancy and Breastfeeding Nutritional Allowance of $40 or $50 a month, until the baby is 12 months old." ]},"steps":["Contact your local ODSP office and ask your caseworker for the form you need.","Take the form to an approved health care professional to fill in.","Return the form to your ODSP office in person or by mail.","Wait for a letter saying whether the expense is approved." ],"documents":["ODSP monthly statement or government photo ID","Ontario health card","Application for Special Diet Allowance (the original form)","Receipts for health costs, for the Extended Health Benefit" ],"tips":["You do not pay a fee to have the forms filled out.","Only the original Special Diet Allowance form is accepted, not a photocopy.","Residents of institutions are not eligible for the Special Diet Allowance.","If you disagree with a decision, ask for an internal review." ],"phone":"1-888-789-4199"}},{"id":"on-oesp","name":"Ontario Electricity Support Program (OESP)","level":"Ontario","category":"Home","amount":"$35 to $75 a month on your bill; $52 to $113 for some households","summary":"A monthly credit on your electricity bill for lower-income households. The amount depends on how many people live in the home and your combined after-tax household income.","note":"Households using certain electricity-intensive medical devices may get a higher credit, between $52 and $113 a month. People on Ontario Works or ODSP qualify automatically and apply through their caseworker.","requires":["on","onOespRoute" ],"eligibility":{"mode":"all","items":["You are the customer of an electricity utility, or a unit sub-meter provider bills you for your own meter.","Your household size and combined after-tax income are within the program's levels." ],"note":"Ontario Works and ODSP recipients automatically qualify and must contact their caseworker to apply."},"applyText":"Apply for OESP","applyUrl":"https://ontarioelectricitysupport.ca/","source":"https://www.oeb.ca/consumer-information-and-protection/bill-assistance-programs/ontario-electricity-support-program","detail":{"aboutList":{"lead":"The OESP puts an ongoing monthly credit directly on your electricity bill.","items":["For example, a 4-person home with $65,000 a year after tax gets a $40 credit each month.","The credit chart covers household after-tax amounts up to $71,000 a year.","Higher credits apply for Indigenous households, electric heating, or certain medical devices.","Credits last 2 years before you reapply, or 5 years if you are 65+ or get a CPP disability pension." ]},"steps":["Gather your electricity bill, the names and birthdates of everyone in your home, and SINs for adults","Apply online at OESP.ca, by mail, or with help from a free intake agency","Sign the consent form that lets the CRA verify your household income for the program","Wait about 4 to 6 weeks for a decision; the credit appears on your bill about 6 to 8 weeks after approval" ],"documents":["Your electricity bill","Names and birthdates of everyone living in your home, as registered with the CRA","Social Insurance Numbers or temporary tax numbers for household members 18 and older" ],"tips":["If you have not filed a tax return recently, or your situation changed, apply through an intake agency and bring proof of income.","If you already get OESP, you must reapply to get a higher credit under the newer income levels.","If you qualify for OESP, you may also apply for emergency grants through the Low-income Energy Assistance Program (LEAP)." ],"time":"About 4 to 6 weeks for a decision","phone":"1-855-831-8151 (TTY 1-800-855-1155)"}},{"id":"on-childrens-rehab","name":"Children's Rehabilitation Services (Children's Treatment Centres)","level":"Ontario","category":"Health (for children)","amount":"Physiotherapy, occupational therapy and speech and language therapy","summary":"Therapy and family supports for children and youth with physical or developmental disabilities or communication difficulties. You do not need a formal referral.","note":"Children's Treatment Centres also give these services in schools to students in Ontario public schools. Students in publicly funded schools may use them until they finish school.","requires":["on","under19","onChildrensRehabRoute" ],"eligibility":{"mode":"all","items":["You are a child or youth up to 19 years old, or up to 21 if you are in school.","You have a physical disability, a developmental disability, or communication difficulties or disorders." ],"note":"A formal referral is not needed, but education or health professionals may refer you."},"applyText":"Find a Children's Treatment Centre","applyUrl":"https://www.ontario.ca/page/childrens-rehabilitation-services","source":"https://www.ontario.ca/page/childrens-rehabilitation-services","detail":{"aboutList":{"lead":"Children's Treatment Centres and Surrey Place in Toronto offer these services.","items":["Physiotherapy helps restore, maintain and make the most of a child's mobility and well-being.","Occupational therapy helps with self-care, productivity and leisure.","Speech and language therapy helps with oral motor and communication function.","SmartStart Hubs in Toronto give families one entry point to assessment and services.","Family supports include respite services and parent coaching." ]},"steps":["Find your area in the table of Children's Treatment Centres on the page.","Contact your local centre, or Surrey Place in Toronto, to talk about your child's development.","The centre can explain which services your child should get and how to reach them.","If you already know what your child needs, you can contact providers directly." ],"documents":["A formal referral is not required" ],"tips":["Contact Empowered Kids Ontario (EKO) for more information about services and locations.","Children from birth until school may also qualify for preschool speech and language services.","You can also call your local ministry regional office for more information." ]}} ]);
